IC.lessonData.push(
{id:'hidden-an-1',title:'أن المضمرة: اللامان وأو وحتى',level:'توسّع',minutes:11,goal:'أن تعرف متى يُنصب المضارع بـ«أن» مضمرة بعد لام التعليل ولام الجحود و«أو» و«حتى»، ومتى يجوز إظهارها.',prereq:'نصب المضارع، والإعراب المحلي',batch:'0.16',source:'النحو الواضح، ج1 ص134',sentence:'جلستُ لأستريحَ.',intro:'قد ينتصب المضارع من غير أن نرى قبله «أن» أو «لن» أو «كي» أو «إذن». في هذه الحال نقدّر قبله «أن» محذوفة. فمتى نقدّرها؟ وهل يجوز إظهارها؟',rule:[['لام التعليل','يُنصب المضارع بعدها بـ«أن» مضمرة جوازًا؛ فنقول: جلستُ لأستريحَ، ويجوز: جلستُ لأنْ أستريحَ.'],['لام الجحود','هي اللام الواقعة بعد «كان» المنفية؛ يُنصب المضارع بعدها بـ«أن» مضمرة وجوبًا، مثل: ما كان الصديقُ ليخونَ صديقَه.'],['أو','التي بمعنى «إلى» أو «إلا»؛ يُنصب المضارع بعدها بـ«أن» مضمرة وجوبًا، مثل: تحبّبْ إلى إخوانك أو تنالَ رضاهم.'],['حتى','يُنصب المضارع بعدها بـ«أن» مضمرة وجوبًا، مثل: لا تأكلْ حتى تجوعَ.']],example:[['حضرتُ لأعودَ المريضَ','«أعودَ» منصوب بـ«أن» مضمرة جوازًا بعد لام التعليل.'],['لم أكنْ لأرافقَ الأشرارَ','«أرافقَ» منصوب بـ«أن» مضمرة وجوبًا بعد لام الجحود.'],['يُعاقَبُ المسيءُ أو يعتذرَ','«يعتذرَ» منصوب بـ«أن» مضمرة وجوبًا بعد «أو» التي بمعنى «إلا».'],['لا تدخلْ حتى يؤذنَ لك','«يؤذنَ» منصوب بـ«أن» مضمرة وجوبًا بعد «حتى».']],tip:'اختبر الجواز والوجوب بالتجربة: إن صحّ أن تظهر «أن» بعد الحرف (لأنْ أستريحَ) فالإضمار جائز، وإن لم يصحّ فالإضمار واجب.',question:'ما حكم إضمار «أن» في: جلستُ لأستريحَ؟',opts:['واجب','جائز','ممنوع'],correct:1,why:'اللام لام التعليل، ويجوز أن نقول: جلستُ لأنْ أستريحَ؛ فالإضمار جائز.'},
{id:'hidden-an-2',title:'أن المضمرة: الفاء والواو',level:'توسّع',minutes:10,goal:'أن تعرف النصب بـ«أن» مضمرة وجوبًا بعد فاء السببية وواو المعية المسبوقتين بنفي أو طلب.',prereq:'أن المضمرة: اللامان وأو وحتى',batch:'0.16',source:'النحو الواضح، ج1 ص139',sentence:'اصنعِ المعروفَ فتنالَ الشكرَ.',intro:'ينتصب المضارع أيضًا بعد فاء أو واو معينة من غير أداة نصب ظاهرة. وهنا لا بد من النظر إلى ما قبل الفاء والواو؛ فهو الذي يحدد الحكم.',rule:[['فاء السببية','الفاء التي يكون ما قبلها سببًا لما بعدها، وتُسبق بنفي أو طلب؛ يُنصب المضارع بعدها بـ«أن» مضمرة وجوبًا، مثل: اصنعِ المعروفَ فتنالَ الشكرَ.'],['واو المعية','الواو التي تفيد مصاحبة ما قبلها لما بعدها، وتُسبق بنفي أو طلب؛ يُنصب المضارع بعدها بـ«أن» مضمرة وجوبًا، مثل: لا تأمرْ بالصدقِ وتكذبَ.'],['الشرط','أن تُسبق الفاء أو الواو بنفي (مثل: لم، ما) أو بطلب (أمر أو نهي)، وبدون ذلك لا تدخل في هذه القاعدة.']],example:[['لم يُسئْ فيُبغَضَ','«يُبغَضَ» منصوب بـ«أن» مضمرة وجوبًا بعد فاء السببية المسبوقة بنفي.'],['اصنعِ المعروفَ فتنالَ الشكرَ','«تنالَ» منصوب بـ«أن» مضمرة وجوبًا بعد فاء السببية المسبوقة بطلب (أمر).'],['لم يفعلِ الخيرَ ويندمَ','«يندمَ» منصوب بـ«أن» مضمرة وجوبًا بعد واو المعية المسبوقة بنفي.'],['لا تأمرْ بالصدقِ وتكذبَ','«تكذبَ» منصوب بـ«أن» مضمرة وجوبًا بعد واو المعية المسبوقة بنهي.']],tip:'إذا رأيت المضارع منصوبًا بعد الفاء أو الواو بلا أداة نصب ظاهرة، فانظر إلى ما قبلهما: هل هو نفي أم طلب؟',question:'لماذا نُصب «تنالَ» في: اصنعِ المعروفَ فتنالَ الشكرَ؟',opts:['بـ«أن» مضمرة وجوبًا بعد فاء السببية المسبوقة بطلب','بـ«لن» مضمرة','لأنه مجزوم'],correct:0,why:'سبقت الفاء بأمر «اصنعِ»، فنُصب المضارع بـ«أن» مضمرة وجوبًا.'}
);
['hidden-an-1','hidden-an-2'].forEach(id=>{const l=IC.lessonData.find(x=>x.id===id);IC.questions.push({id:'q-'+l.id,lessonId:l.id,skill:l.title,difficulty:'متوسط',prompt:l.question,sentence:l.sentence,options:l.opts.map((text,j)=>({text,correct:j===l.correct})),explanation:l.why,correctIndex:l.correct,misconception:'الخلط بين الجواز والوجوب في إضمار أن'});});

IC.lessonDetails['hidden-an-1']={sentenceExplanation:'سُبق «أستريحَ» بلام التعليل ولا أداة نصب ظاهرة قبله، فهو منصوب بـ«أن» مضمرة جوازًا.',fullParse:[['جلستُ','فعل ماضٍ مبني على السكون لاتصاله بتاء الفاعل، والتاء ضمير متصل مبني على الضم في محل رفع فاعل.'],['اللام','حرف جر (لام التعليل) مبني على الكسر.'],['أستريحَ','فعل مضارع منصوب بـ«أن» مضمرة جوازًا بعد لام التعليل، وعلامة نصبه الفتحة الظاهرة، والفاعل ضمير مستتر تقديره «أنا».']],lessonTemplateVersion:1,reviewStatus:R,
learningSteps:[{title:'ابحث عن أداة النصب',text:'هل قبل المضارع «أن» أو «لن» أو «كي» أو «إذن»؟ إن لم تجدها وهو منصوب فقد أُضمرت «أن».'},{title:'حدّد ما قبل الفعل',text:'لام تعليل؟ لام جحود بعد «كان» المنفية؟ «أو» بمعنى إلى أو إلا؟ «حتى»؟'},{title:'حدّد حكم الإضمار',text:'جرّب إظهار «أن»: إن صحّ فهو جائز (لام التعليل)، وإن لم يصحّ فهو واجب (البقية).'}],
workedExamples:[{sentence:'يجتهدُ الطالبُ لينجحَ.',meaning:'المعنى: يجتهد الطالب من أجل النجاح.',parse:[['يجتهدُ','فعل مضارع مرفوع، وعلامة رفعه الضمة الظاهرة.'],['الطالبُ','فاعل مرفوع، وعلامة رفعه الضمة الظاهرة.'],['اللام','حرف جر (لام التعليل) مبني على الكسر.'],['ينجحَ','فعل مضارع منصوب بـ«أن» مضمرة جوازًا بعد لام التعليل، وعلامة نصبه الفتحة الظاهرة.']]},{sentence:'ما كان الصديقُ ليخونَ صديقَه.',meaning:'المعنى: لا يصح من الصديق أن يخون صديقه.',parse:[['ما','حرف نفي مبني على السكون.'],['كان','فعل ماضٍ ناقص مبني على الفتح.'],['الصديقُ','اسم كان مرفوع، وعلامة رفعه الضمة الظاهرة.'],['اللام','لام الجحود، حرف جر مبني على الكسر.'],['يخونَ','فعل مضارع منصوب بـ«أن» مضمرة وجوبًا بعد لام الجحود، وعلامة نصبه الفتحة الظاهرة.'],['صديقَه','مفعول به منصوب، وعلامة نصبه الفتحة الظاهرة، وهو مضاف، والهاء ضمير متصل مبني على الضم في محل جر مضاف إليه.']]},{sentence:'لا تدخلْ حتى يؤذنَ لك.',meaning:'المعنى: انتظر حتى يسمحوا لك.',parse:[['لا','حرف نهي وجزم مبني على السكون.'],['تدخلْ','فعل مضارع مجزوم بـ«لا» الناهية، وعلامة جزمه السكون، والفاعل ضمير مستتر تقديره «أنتَ».'],['حتى','حرف غاية مبني على السكون.'],['يؤذنَ','فعل مضارع مبني للمجهول منصوب بـ«أن» مضمرة وجوبًا بعد «حتى»، وعلامة نصبه الفتحة الظاهرة.'],['لك','اللام حرف جر مبني على الكسر، والكاف ضمير متصل مبني على الفتح في محل جر باللام.']]}],
guidedPractice:{prompt:'بيّن سبب نصب «ينالَ» في: لا يُمدحُ الولدُ حتى ينالَ رضا والديه.',hint:'هل قبل «ينالَ» أداة نصب ظاهرة؟ وما الحرف الذي سبقه؟',answer:'«ينالَ» فعل مضارع منصوب بـ«أن» مضمرة وجوبًا بعد «حتى»، وعلامة نصبه الفتحة الظاهرة.',explanation:'«أن» لا تظهر بعد «حتى»، فإضمارها واجب.'},
summary:['إذا نُصب المضارع بلا أداة ظاهرة فالناصب «أن» مضمرة.','بعد لام التعليل يجوز إضمارها وإظهارها.','وبعد لام الجحود و«أو» (بمعنى إلى أو إلا) و«حتى» يجب إضمارها.'],
commonMistakes:['القول إن المضارع منصوب بلا ناصب؛ فالناصب «أن» مضمرة.','الخلط بين لام التعليل ولام الجحود؛ فلام الجحود تقع بعد «كان» المنفية ولا تفيد التعليل.'],
bookExamples:['جلستُ لأستريحَ.','حضرتُ لأعودَ المريضَ.','يجتهدُ الطالبُ لينجحَ.','بنيتُ بيتًا لأسكنَ فيه.','ما كان الصديقُ ليخونَ صديقَه.','ما كانت الطيورُ لتُسجنَ في الأقفاصِ.','لم يكن الشرطيُّ ليسرقَ.','لم أكنْ لأرافقَ الأشرارَ.','استمعْ نصحَ الطبيبِ أو يتمَّ شفاؤك.','تحبّبْ إلى إخوانك أو تنالَ رضاهم.','يُعاقَبُ المسيءُ أو يعتذرَ.','يُحرَمُ التلميذُ المكافأةَ أو يجتهدَ.','لا يُمدحُ الولدُ حتى ينالَ رضا والديه.','سألزمُ الفراشَ حتى يتمَّ شفائي.','لا تأكلْ حتى تجوعَ.','لا تدخلْ حتى يؤذنَ لك.'],
inquiry:['في الأمثلة الأولى مضارعات مسبوقة بلام تفيد أن ما بعدها علة وسبب لما قبلها؛ فالاستراحة علة الجلوس، وعيادة المريض علة الحضور. ولذلك تسمى لام التعليل. وهذه الأفعال منصوبة ولا نرى قبلها أداة نصب ظاهرة، والنصب لا يكون إلا بـ«أن» و«لن» و«إذن» و«كي»؛ فلا بد من إضمار إحداها. ونعرف أنها «أن» لأن الأفعال نفسها تأتي بعد اللام منصوبة بـ«أن» الظاهرة: جلستُ لأنْ أستريحَ. فالإضمار هنا جائز.','وفي الأمثلة التالية لام لا تفيد التعليل، وتقع دائمًا بعد «كان» المنفية؛ ولذلك تسمى لام الجحود (النفي). والأفعال بعدها منصوبة ولا أداة ظاهرة، ولا يستقيم المعنى إلا بتقدير «أن». ولأن «أن» لا تظهر بعد هذه اللام فإضمارها واجب.','وفي أمثلة «أو»: يصح أن نضع «إلى» مكانها في المثالين الأولين: استمع نصح الطبيب إلى أن يتم شفاؤك. ويصح أن نضع «إلا» في الآخرين: يعاقَب المسيء إلا أن يعتذر. والمضارع بعدها منصوب بلا أداة ظاهرة؛ فهو منصوب بـ«أن» مضمرة وجوبًا لأنها لا تظهر هنا.','وفي أمثلة «حتى»: المضارع بعدها منصوب بلا أداة ظاهرة، والناصب «أن» مضمرة. وإضمارها واجب لأنها لا تظهر أبدًا بعد «حتى».'],
exercises:[{title:'تمرين 1',tasks:[{ask:'عيّن المضارع المنصوب بـ«أن» المضمرة في كل جملة، واذكر الحرف الذي سبقه',items:['ذهبتُ إلى المكتبةِ لأستعيرَ كتابًا.','ما كان المعلمُ ليظلمَ تلميذًا.','سأنتظرُ حتى يعودَ أخي.','سأصبرُ أو يأتيَ الفرجُ.']}]},{title:'تمرين 2',tasks:[{ask:'أتمم الجمل الآتية بمضارع منصوب بـ«أن» المضمرة، واضبط آخره',items:['درستُ لـ ...','ما كان الجنديُّ لـ ...','لا تغادرِ المكانَ حتى ...','سأنتظرك أو ...']}]},{title:'تمرين 3',tasks:[{ask:'ائت بجملتين فيهما المضارع منصوب بـ«أن» المضمرة بعد لام التعليل',items:[]},{ask:'ائت بجملتين فيهما المضارع منصوب بـ«أن» المضمرة بعد لام الجحود',items:[]},{ask:'ائت بجملتين فيهما المضارع منصوب بـ«أن» المضمرة بعد «أو»',items:[]},{ask:'ائت بجملتين فيهما المضارع منصوب بـ«أن» المضمرة بعد «حتى»',items:[]}]},{title:'تمرين 4 في الإعراب',tasks:[{model:true,ask:'نموذج',items:['درستُ لأنجحَ.','درستُ: فعل ماضٍ مبني على السكون لاتصاله بتاء الفاعل، والتاء ضمير متصل في محل رفع فاعل.','اللام: حرف جر مبني على الكسر.','أنجحَ: فعل مضارع منصوب بأن مضمرة جوازًا بعد لام التعليل، وعلامة نصبه الفتحة، والفاعل ضمير مستتر تقديره «أنا».']},{ask:'أعرب الجملتين الآتيتين',items:['ما كان الجنديُّ ليهربَ.','لا تغادرِ المكانَ حتى يعودَ المعلمُ.']}]}]};

IC.lessonDetails['hidden-an-2']={sentenceExplanation:'سُبقت الفاء بأمر (طلب)، والمضارع «تنالَ» منصوب بلا أداة ظاهرة، فالناصب «أن» مضمرة وجوبًا.',fullParse:[['اصنعِ','فعل أمر مبني على السكون، والفاعل ضمير مستتر تقديره «أنتَ».'],['المعروفَ','مفعول به منصوب، وعلامة نصبه الفتحة الظاهرة.'],['الفاء','فاء السببية حرف مبني على الفتح.'],['تنالَ','فعل مضارع منصوب بـ«أن» مضمرة وجوبًا بعد فاء السببية، وعلامة نصبه الفتحة الظاهرة، والفاعل ضمير مستتر تقديره «أنتَ».'],['الشكرَ','مفعول به منصوب، وعلامة نصبه الفتحة الظاهرة.']],lessonTemplateVersion:1,reviewStatus:R,
learningSteps:[{title:'ابحث عن الفاء أو الواو',text:'هل سبق المضارع المنصوب فاء أو واو، ولا توجد أداة نصب ظاهرة؟'},{title:'انظر إلى ما قبلها',text:'هل قبلها نفي (لم، ما، لا النافية) أو طلب (أمر، نهي)؟'},{title:'سمِّ الفاء أو الواو',text:'الفاء فاء السببية (ما قبلها سبب لما بعدها)، والواو واو المعية (مصاحبة ما قبلها لما بعدها)، والناصب «أن» مضمرة وجوبًا.'}],
workedExamples:[{sentence:'ما درسَ الطالبُ فينجحَ.',meaning:'المعنى: لم يدرس الطالب فلا ينجح.',parse:[['ما','حرف نفي مبني على السكون.'],['درسَ','فعل ماضٍ مبني على الفتح.'],['الطالبُ','فاعل مرفوع، وعلامة رفعه الضمة الظاهرة.'],['الفاء','فاء السببية حرف مبني على الفتح.'],['ينجحَ','فعل مضارع منصوب بـ«أن» مضمرة وجوبًا بعد فاء السببية المسبوقة بنفي، وعلامة نصبه الفتحة الظاهرة.']]},{sentence:'لا تأمرْ بالصدقِ وتكذبَ.',meaning:'المعنى: لا تجمع بين الأمر بالصدق والكذب.',parse:[['لا','حرف نهي وجزم مبني على السكون.'],['تأمرْ','فعل مضارع مجزوم بـ«لا» الناهية، وعلامة جزمه السكون، والفاعل ضمير مستتر تقديره «أنتَ».'],['بالصدقِ','الباء حرف جر مبني على الكسر، والصدقِ مجرور بالباء وعلامة جره الكسرة الظاهرة.'],['الواو','واو المعية حرف مبني على الفتح.'],['تكذبَ','فعل مضارع منصوب بـ«أن» مضمرة وجوبًا بعد واو المعية المسبوقة بنهي، وعلامة نصبه الفتحة الظاهرة.']]},{sentence:'لا تُهملْ دروسَك فترسبَ.',meaning:'المعنى: لا تُهمل دروسك حتى لا ترسب.',parse:[['لا','حرف نهي وجزم مبني على السكون.'],['تُهملْ','فعل مضارع مجزوم بـ«لا» الناهية، وعلامة جزمه السكون، والفاعل ضمير مستتر تقديره «أنتَ».'],['دروسَك','مفعول به منصوب، وعلامة نصبه الفتحة الظاهرة، وهو مضاف، والكاف ضمير متصل مبني على الفتح في محل جر مضاف إليه.'],['الفاء','فاء السببية حرف مبني على الفتح.'],['ترسبَ','فعل مضارع منصوب بـ«أن» مضمرة وجوبًا بعد فاء السببية المسبوقة بنهي، وعلامة نصبه الفتحة الظاهرة.']]}],
guidedPractice:{prompt:'بيّن سبب نصب «تُحبَّ» في: كنْ ليّنَ الجانبِ فتُحبَّ.',hint:'ما الذي سبق الفاء؟',answer:'«تُحبَّ» فعل مضارع منصوب بـ«أن» مضمرة وجوبًا بعد فاء السببية المسبوقة بطلب (أمر)، وعلامة نصبه الفتحة الظاهرة.',explanation:'سبقت الفاء بأمر «كنْ»، و«أن» لا تظهر بعدها.'},
summary:['ينصب المضارع بـ«أن» مضمرة وجوبًا بعد فاء السببية المسبوقة بنفي أو طلب.','وينصب بـ«أن» مضمرة وجوبًا بعد واو المعية المسبوقة بنفي أو طلب.','الفاء يكون ما قبلها سببًا لما بعدها، والواو تفيد مصاحبة ما قبلها لما بعدها.'],
commonMistakes:['رفع المضارع أو جزمه بعد الفاء والواو في هذا الموضع؛ والصواب نصبه.','نسيان شرط النفي أو الطلب قبل الفاء أو الواو.'],
bookExamples:['لم يُسئْ فيُبغَضَ.','لم يُسألْ فيجيبَ.','اصنعِ المعروفَ فتنالَ الشكرَ.','كنْ ليّنَ الجانبِ فتُحبَّ.','لم يفعلِ الخيرَ ويندمَ.','لم يواسِ الفقيرَ ويمنَّ عليه.','لا تأمرْ بالصدقِ وتكذبَ.','لا تنظرْ إلى عيوبِ الناسِ وتُهملَ عيوبَ نفسِك.'],
inquiry:['انظر إلى المضارعات: يُبغَضَ، ويجيبَ، وتنالَ، وتُحبَّ. كل منها مسبوق بفاء تفيد أن ما قبلها سبب في حصول ما بعدها؛ فالإساءة سبب البغض، والسؤال سبب الإجابة. ولذلك تسمى فاء السببية. وهي مسبوقة بنفي في المثالين الأولين، وبطلب في الآخرين. والفعل بعدها منصوب ولا أداة نصب ظاهرة؛ فالنصب بـ«أن» المحذوفة، وحذفها هنا واجب لأن النصب لا يظهر بعد هذه الفاء بحال.','وانظر إلى المضارعات: يندمَ، ويمنَّ، وتكذبَ، وتُهملَ. كل منها مسبوق بواو تفيد مصاحبة ما قبلها لما بعدها، وإن شئت فقل: تفيد نفي حصول ما قبلها وما بعدها معًا. ولذلك تسمى واو المصاحبة أو واو المعية. وقبلها نفي في المثالين الأولين، وطلب في الآخرين.','وآخر كل مضارع بعد هذه الواو منصوب بلا أداة ظاهرة؛ فالنصب بـ«أن» المضمرة وجوبًا، قياسًا على ما سبق.'],
exercises:[{title:'تمرين 1',tasks:[{ask:'عيّن الأفعال المضارعة المنصوبة في العبارات الآتية، وبيّن ما نُصب منها بأن المحذوفة جوازًا، والمحذوفة وجوبًا',items:['مرّ عمر بن الخطاب بصبيان يلعبون، وفيهم عبد الله حفيد العوام، فلما لمحوه هربوا من وجهه إلا عبد الله، فما كان ليفرّ، فقال له عمر: ما لك لم تهرب مع رفقائك؟ فقال: يا أمير المؤمنين، لم أكن على ريبة فأخاف سطوتك، ولم تكن الطريق ضيقة فأوسع لك. فعجب عمر من فطنته وسرعة خاطره.','خرجنا إلى الحقول لنريح نفوسنا من عناء العمل، ولن نعود حتى تغيب الشمس.','لم يكن الغنى ليطغي كرام النفوس، ولم يكن الوالد ليخاف أباه.','لا تكثر معاتبة الصديق فيهون عليه سخطك.','لم يأمر الناصح بالأمانة ويخون، ولم يتول القاضي الحكم ويظلم.','لا تكن رطبًا فتعصر، ولا يابسًا فتكسر.']}]},{title:'تمرين 2',tasks:[{ask:'أتمم الجمل الآتية بذكر الفعل المضارع المحذوف، واضبط آخره وبيّن سبب الضبط',items:['لم يطلب المساعدة فـ ...','لا تفش سر أخيك فـ ...','لم يدّخر مالًا في زمن الرخاء فـ ...','لا تقرأ في الضوء الضعيف فـ ...','لا تنه عن منكر و ...','لا تحض على إطعام المسكين و ...','لم يغضب أحد والديه و ...','لم يزرع أحد جميلًا و ...','ما كنت لـ ...','لم يكن الخادم لـ ...','جاء الطبيب لـ ...','لن أنام حتى ...']}]},{title:'تمرين 3',tasks:[{ask:'اذكر الجمل المحذوفة المتممة للمعنى فيما يأتي',items:['... فتدومَ لك صداقته.','... فتكسدَ تجارتك.','... فيبتعدَ عنك إخوانك.','... حتى تستريحَ في كِبَرِك.','... لتستحقَّ حمد الناس.','... أو تصلَ إلى مقصودك.']}]},{title:'تمرين 4',tasks:[{ask:'ائت بجملتين فيهما المضارع منصوب بأن المضمرة بعد لام التعليل',items:[]},{ask:'ائت بجملتين فيهما المضارع منصوب بأن المضمرة بعد لام الجحود',items:[]},{ask:'ائت بجملتين فيهما المضارع منصوب بأن المضمرة بعد حتى',items:[]},{ask:'ائت بجملتين فيهما المضارع منصوب بأن المضمرة بعد فاء السببية',items:[]},{ask:'ائت بجملتين فيهما المضارع منصوب بأن المضمرة بعد واو المعية',items:[]},{ask:'ائت بجملتين فيهما المضارع منصوب بأن المضمرة بعد أو',items:[]}]},{title:'تمرين 5',tasks:[{ask:'أجب عن الأسئلة الآتية بجمل تشتمل كل منها على مضارع منصوب بأن المضمرة',items:['لمَ يسافر الطلاب إلى البلاد الأجنبية؟','أأنت ممن يقصّرون في واجبهم؟','إلى متى تظل تلميذًا بالمدارس الابتدائية؟','إلى متى تبقى المصابيح موقدة؟']}]},{title:'تمرين 6 في الإعراب',tasks:[{model:true,ask:'نموذج',items:['لم تذنبِ البنتُ فتخافَ.','لم: حرف نفي وجزم مبني على السكون.','تذنب: فعل مضارع مجزوم بلم وعلامة جزمه السكون.','البنتُ: فاعل مرفوع بالضمة.','فتخاف: الفاء فاء للسببية حرف مبني على الفتح، وتخاف فعل مضارع منصوب بأن مضمرة وجوبًا وعلامة نصبه الفتحة.']},{ask:'أعرب الجملتين الآتيتين',items:['لم يجهلِ الرجلُ السباحةَ فيغرقَ.','لا تتأخرْ فيفوتَك القطارُ.']}]}],exercisesFromBook:true};

