IC.lessonData.push(
{id:'lamma-lam-amr',title:'لمّا ولام الأمر',level:'توسّع',minutes:9,goal:'أن تعرف حرفين يجزمان فعلًا مضارعًا واحدًا: «لمّا» ولام الأمر، وتعرب ما بعدهما.',prereq:'جزم المضارع بـ«لم» و«لا» الناهية',batch:'0.17',source:'النحو الواضح، ج1 ص145',sentence:'ذهب الرسولُ ولمّا يعدْ.',intro:'عرفتَ أن «لم» و«لا» الناهية تجزمان فعلًا مضارعًا واحدًا. وهناك حرفان آخران يعملان هذا العمل، ولكل منهما معناه الخاص.',rule:[['لمّا','حرف نفي وجزم؛ تشبه «لم» في المعنى والعمل، لكن النفي بها يستمر إلى زمن التكلم، مثل: ذهب الرسولُ ولمّا يعدْ.'],['لام الأمر','حرف يجعل المضارع مفيدًا للأمر ويجزمه، مثل: ليفتحْ عليٌّ النافذةَ.'],['علامة الجزم','السكون في المضارع الصحيح الآخر، وحذف حرف العلة في المعتل الآخر، مثل: لمّا يأتِ، ليدعُ.']],example:[['كبر الغلامُ ولمّا يتهذّبْ','«يتهذّبْ» مجزوم بـ«لمّا» وعلامة جزمه السكون؛ والنفي مستمر إلى الآن.'],['ذهب الرسولُ ولمّا يعدْ','«يعدْ» مجزوم بـ«لمّا» وعلامة جزمه السكون.'],['ليفتحْ عليٌّ النافذةَ','«يفتحْ» مجزوم بلام الأمر وعلامة جزمه السكون.'],['ليتقنْ كلُّ إنسانٍ عملَه','«يتقنْ» مجزوم بلام الأمر، وأفادت اللام معنى الأمر.']],tip:'لا تخلط بين لام الأمر ولام التعليل: لام الأمر تجزم المضارع وتفيد الطلب (ليفتحْ)، ولام التعليل ينصب المضارع بعدها بـ«أن» مضمرة (جلستُ لأستريحَ).',question:'ما الذي أفاده دخول اللام على «يفتح» في: ليفتحْ عليٌّ النافذةَ؟',opts:['الاستفهام','الأمر مع جزم الفعل','النفي'],correct:1,why:'لام الأمر تفيد الطلب وتجزم المضارع بعدها.'},
{id:'shart-jazim',title:'أدوات الشرط الجازمة',level:'توسّع',minutes:12,goal:'أن تعرف أدوات الشرط التي تجزم فعلين، وتعيّن فعل الشرط وجوابه وتعرب كلًّا منهما.',prereq:'لمّا ولام الأمر',batch:'0.17',source:'النحو الواضح، ج1 ص148',sentence:'من يفرطْ في الأكلِ يتخمْ.',intro:'بعض الأدوات تجزم فعلين مضارعين معًا، ويتوقف حصول الثاني على حصول الأول. فما هذه الأدوات؟ وما معنى كل منها؟',rule:[['فعل الشرط وجوابه','تجزم أدوات الشرط فعلين مضارعين: الأول فعل الشرط، والثاني جوابه وجزاؤه، ويتوقف حصول الثاني على حصول الأول.'],['الأدوات','اثنتا عشرة أداة: حرفان هما «إنْ» و«إذ ما»، وعشرة أسماء هي: مَن، ما، مهما، متى، أيان، أين، أنّى، حيثما، كيفما، أيّ.'],['معانيها','«مَن» للعاقل، و«ما» و«مهما» لغير العاقل، و«متى» و«أيان» للزمان، و«أين» و«أنّى» و«حيثما» للمكان، و«كيفما» للحال، و«أيّ» تصلح لجميع هذه المعاني.']],example:[['مَن يفرطْ في الأكلِ يتخمْ','«يفرطْ» فعل الشرط، و«يتخمْ» جوابه؛ وكلاهما مجزوم بالسكون.'],['ما تدخرْ من مالِك ينفعْك','«ما» اسم شرط لغير العاقل؛ و«تدخرْ» و«ينفعْ» مجزومان.'],['متى يسافرْ أخي أسافرْ معه','«متى» للزمان؛ و«يسافرْ» فعل الشرط و«أسافرْ» جوابه.'],['أين تذهبْ أصحبْك','«أين» للمكان؛ و«تذهبْ» فعل الشرط و«أصحبْ» جوابه.']],tip:'ابحث عن فعلين مضارعين مجزومين متتاليين يتوقف الثاني على الأول؛ فقبل الأول أداة شرط. وإن كان الفعل معتل الآخر فجزمه بحذف حرف العلة، مثل: من يجتنبْ أذى الناسِ ينجُ.',question:'ما فعل الشرط في: مَن يفرطْ في الأكلِ يتخمْ؟',opts:['يتخمْ','يفرطْ','الأكلِ'],correct:1,why:'«يفرطْ» هو الفعل الأول الذي يتوقف عليه حصول الثاني، فهو فعل الشرط.'}
);
['lamma-lam-amr','shart-jazim'].forEach(id=>{const l=IC.lessonData.find(x=>x.id===id);IC.questions.push({id:'q-'+l.id,lessonId:l.id,skill:l.title,difficulty:'متوسط',prompt:l.question,sentence:l.sentence,options:l.opts.map((text,j)=>({text,correct:j===l.correct})),explanation:l.why,correctIndex:l.correct,misconception:'الخلط بين أدوات الجزم ومعانيها'});});

IC.lessonDetails['lamma-lam-amr']={sentenceExplanation:'دخلت «لمّا» على «يعدْ» فنفت عودة الرسول واستمر هذا النفي إلى زمن التكلم، وجُزم الفعل بالسكون.',fullParse:[['ذهب','فعل ماضٍ مبني على الفتح.'],['الرسولُ','فاعل مرفوع، وعلامة رفعه الضمة الظاهرة.'],['الواو','حرف مبني على الفتح للربط بين الجملتين.'],['لمّا','حرف نفي وجزم مبني على السكون.'],['يعدْ','فعل مضارع مجزوم بـ«لمّا»، وعلامة جزمه السكون، والفاعل ضمير مستتر تقديره «هو».']],lessonTemplateVersion:1,reviewStatus:R,
learningSteps:[{title:'انظر إلى معنى الجملة',text:'هل تنفي حصول الفعل إلى الآن (لمّا)؟ أم تأمر به (لام الأمر)؟'},{title:'انظر إلى آخر المضارع',text:'هو مجزوم في الحالتين: بالسكون إن كان صحيحًا، وبحذف حرف العلة إن كان معتلًّا.'},{title:'سمِّ الجازم',text:'«لمّا» حرف نفي وجزم، ولام الأمر حرف أمر وجزم.'}],
workedExamples:[{sentence:'ذهب الرسولُ ولمّا يعدْ.',meaning:'المعنى: ذهب الرسول ولم يرجع إلى الآن.',parse:[['ذهب','فعل ماضٍ مبني على الفتح.'],['الرسولُ','فاعل مرفوع، وعلامة رفعه الضمة الظاهرة.'],['لمّا','حرف نفي وجزم مبني على السكون.'],['يعدْ','فعل مضارع مجزوم بـ«لمّا»، وعلامة جزمه السكون.']]},{sentence:'حضرتُ ولمّا يأتِ المعلمُ.',meaning:'المعنى: حضرتُ وما جاء المعلم إلى الآن.',parse:[['حضرتُ','فعل ماضٍ مبني على السكون لاتصاله بتاء الفاعل، والتاء ضمير متصل مبني على الضم في محل رفع فاعل.'],['لمّا','حرف نفي وجزم مبني على السكون.'],['يأتِ','فعل مضارع مجزوم بـ«لمّا»، وعلامة جزمه حذف الياء.'],['المعلمُ','فاعل مرفوع، وعلامة رفعه الضمة الظاهرة.']]},{sentence:'ليفتحْ عليٌّ النافذةَ.',meaning:'المعنى: يُطلب من علي أن يفتح النافذة.',parse:[['اللام','لام الأمر حرف جزم مبني على الكسر.'],['يفتحْ','فعل مضارع مجزوم بلام الأمر، وعلامة جزمه السكون.'],['عليٌّ','فاعل مرفوع، وعلامة رفعه الضمة الظاهرة.'],['النافذةَ','مفعول به منصوب، وعلامة نصبه الفتحة الظاهرة.']]}],
guidedPractice:{prompt:'أعرب «يقرأْ» في: ليقرأْ كلُّ طالبٍ درسَه.',hint:'ما الأداة التي دخلت عليه؟ وما معناها؟',answer:'«يقرأْ» فعل مضارع مجزوم بلام الأمر، وعلامة جزمه السكون.',explanation:'اللام أفادت الأمر وجزمت الفعل، وآخر الفعل صحيح فجُزم بالسكون.'},
summary:['«لمّا» حرف نفي وجزم، والنفي بها يستمر إلى زمن التكلم.','لام الأمر حرف يجعل المضارع مفيدًا للأمر ويجزمه.','علامة الجزم: السكون في الصحيح الآخر، وحذف حرف العلة في المعتل الآخر.'],
commonMistakes:['عدّ لام الأمر لام تعليل؛ فلام التعليل ينصب المضارع بـ«أن» مضمرة.','رفع الفعل أو نصبه بعد «لمّا» ولام الأمر؛ والصواب جزمه.'],
bookExamples:['كبر الغلامُ ولمّا يتهذّبْ.','ذهب الرسولُ ولمّا يعدْ.','بنى الأميرُ قصرًا ولم يسكنْه.','طاب الزرعُ ولمّا يحصدْ.','لتجتنبْ كثرةَ المزاحِ.','ليفتحْ عليٌّ النافذةَ.','ليتقنْ كلُّ إنسانٍ عملَه.','ليوقّرْ صغيرُكم كبيرَكم.'],
inquiry:['تقدم لنا أن «لم» و«لا» الناهية تجزمان فعلًا مضارعًا واحدًا، وهنا نأتي على بقية الأدوات التي تعمل هذا العمل. في الأمثلة الأربعة الأولى: الغلام لم يتهذب في الزمن الماضي وبقي كذلك إلى زمن المتكلم، والرسول لم يعد وبقي كذلك إلى زمن التكلم. فهذه الأمثلة تفيد نفي الأفعال، وهذا النفي مستمر إلى زمن التكلم، وآخر أفعالها مجزوم. واللفظ الذي أفاد النفي وسبّب الجزم هو «لمّا»، فهي تشبه «لم» في المعنى والعمل، غير أن النفي بها يستمر إلى زمن التكلم.','وفي الأمثلة الأربعة الأخيرة يأمر المتكلم المخاطب باجتناب المزاح الكثير، ويأمر عليًّا بفتح النافذة، ويأمر بالإتقان والتوقير. فالأفعال المضارعة فيها صارت مفيدة للأمر، وكلها مجزومة. وما أكسبها معنى الأمر وجزم أواخرها هو اللام التي دخلت عليها؛ ولذلك سميت لام الأمر.'],
exercises:[{title:'تمرين 1',tasks:[{ask:'ضع الأفعال المضارعة الآتية في جمل مفيدة، وأدخل عليها «لمّا» واضبط أواخرها',items:['يسافر','يقرأ','يأتي','ينسى','يفهم','يصفو']}]},{title:'تمرين 2',tasks:[{ask:'ضع الأفعال المضارعة الآتية في جمل مفيدة، وأدخل عليها لام الأمر واضبط أواخرها',items:['يدعو','يأمر','يغفر','يسمع','يرمي','ينتبه','يرضى']}]},{title:'تمرين 3',tasks:[{ask:'اقرأ الأمثلة الآتية وضع «لمّا» بدلًا من «لم» في كل مثال يصلح فيه ذلك',items:['لم نذهب إلى الحديقة أمس.','لم يحضر والدي من السفر.','نزل المطر ولم ينقطع.','لم أزر البارحة أحدًا.','لم تربح تجارتنا في العام الماضي.','ضاعت عصاي ولم أجدها.']}]},{title:'تمرين 4',tasks:[{ask:'ضع بدل كل جملة من الجمل الآتية جملة أخرى موافقة لها في المعنى بحيث يكون فعلها مضارعًا',items:['ما سافر أخي إلى الآن.','نم مبكرًا واستيقظ مبكرًا.','ارحم الضعيف.','ما انتهى الشتاء إلى الآن.','استمع نصح والدك.','اغسل فمك قبل النوم.']}]},{title:'تمرين 5',tasks:[{ask:'كوّن جملتين في كل منهما فعل مضارع صحيح الآخر مجزوم بلمّا',items:[]},{ask:'كوّن جملتين في كل منهما فعل مضارع معتل الآخر مجزوم بلمّا',items:[]},{ask:'كوّن جملتين في كل منهما فعل مضارع صحيح الآخر مجزوم بلام الأمر',items:[]},{ask:'كوّن جملتين في كل منهما فعل مضارع معتل الآخر مجزوم بلام الأمر',items:[]}]}],exercisesFromBook:true};

IC.lessonDetails['shart-jazim']={sentenceExplanation:'دخلت «مَن» على فعلين: «يفرطْ» فعل الشرط، و«يتخمْ» جوابه، فجُزم الفعلان بالسكون.',fullParse:[['مَن','اسم شرط جازم مبني على السكون في محل رفع مبتدأ.'],['يفرطْ','فعل الشرط، فعل مضارع مجزوم بـ«مَن» وعلامة جزمه السكون.'],['في','حرف جر مبني على السكون.'],['الأكلِ','اسم مجرور بـ«في»، وعلامة جره الكسرة الظاهرة.'],['يتخمْ','جواب الشرط، فعل مضارع مجزوم، وعلامة جزمه السكون.']],lessonTemplateVersion:1,reviewStatus:R,
learningSteps:[{title:'ابحث عن الفعلين المجزومين',text:'هل في الجملة فعلان مضارعان مجزومان يتوقف الثاني على الأول؟'},{title:'حدّد الأداة',text:'الأداة قبل الفعلين: «مَن» للعاقل، «ما» لغير العاقل، «متى» للزمان، «أين» للمكان، «كيفما» للحال.'},{title:'سمِّ الفعلين',text:'الأول فعل الشرط، والثاني جواب الشرط، وكلاهما مجزوم.'}],
workedExamples:[{sentence:'ما تدخرْ من مالِك ينفعْك.',meaning:'المعنى: ما توفّره من مالك يفيدك.',parse:[['ما','اسم شرط جازم مبني على السكون في محل نصب مفعول به.'],['تدخرْ','فعل الشرط، فعل مضارع مجزوم بـ«ما» وعلامة جزمه السكون، والفاعل ضمير مستتر تقديره «أنتَ».'],['من','حرف جر مبني على السكون.'],['مالِك','اسم مجرور بـ«من»، وعلامة جره الكسرة الظاهرة، وهو مضاف، والكاف ضمير متصل مبني على الفتح في محل جر مضاف إليه.'],['ينفعْك','جواب الشرط، فعل مضارع مجزوم وعلامة جزمه السكون، والكاف ضمير متصل في محل نصب مفعول به، والفاعل ضمير مستتر تقديره «هو».']]},{sentence:'من يجتنبْ أذى الناسِ ينجُ.',meaning:'المعنى: من ابتعد عن إيذاء الناس سلم.',parse:[['مَن','اسم شرط جازم مبني على السكون في محل رفع مبتدأ.'],['يجتنبْ','فعل الشرط، فعل مضارع مجزوم بـ«مَن» وعلامة جزمه السكون.'],['أذى','مفعول به منصوب، وعلامة نصبه فتحة مقدّرة على الألف للتعذر، وهو مضاف.'],['الناسِ','مضاف إليه مجرور، وعلامة جره الكسرة الظاهرة.'],['ينجُ','جواب الشرط، فعل مضارع معتل الآخر مجزوم، وعلامة جزمه حذف الواو.']]},{sentence:'أين تذهبْ أصحبْك.',meaning:'المعنى: في أي مكان تذهب أرافقك.',parse:[['أين','اسم شرط جازم للمكان مبني على الفتح في محل نصب ظرف مكان.'],['تذهبْ','فعل الشرط، فعل مضارع مجزوم بـ«أين» وعلامة جزمه السكون، والفاعل ضمير مستتر تقديره «أنتَ».'],['أصحبْك','جواب الشرط، فعل مضارع مجزوم وعلامة جزمه السكون، والفاعل ضمير مستتر تقديره «أنا»، والكاف ضمير متصل في محل نصب مفعول به.']]}],
guidedPractice:{prompt:'عيّن فعل الشرط وجوابه في: من يسافرْ تزددْ تجاربُه.',hint:'ابحث عن الفعلين المجزومين، وانظر أيهما يتوقف على الآخر.',answer:'فعل الشرط «يسافرْ»، وجوابه «تزددْ»، وكلاهما مجزوم بالسكون.',explanation:'ازدياد التجارب يتوقف على السفر، فالسفر شرط والازدياد جزاء.'},
summary:['تجزم أدوات الشرط فعلين مضارعين: فعل الشرط وجوابه.','الأدوات اثنتا عشرة: «إنْ» و«إذ ما» حرفان، والبقية أسماء.','تتعدد معاني الأسماء: للعاقل، ولغير العاقل، وللزمان، وللمكان، وللحال.'],
commonMistakes:['رفع فعل الشرط أو جوابه بعد الأداة؛ والصواب جزمهما.','نسيان أن المعتل الآخر يُجزم بحذف حرف العلة: من يجتنبْ أذى الناسِ ينجُ.'],
bookExamples:['من يفرطْ في الأكلِ يتخمْ.','من يتعبْ في صغرِه يتمتعْ في كبرِه.','من يجتنبْ أذى الناسِ ينجُ من أذاهم.','من يسافرْ تزددْ تجاربُه.','ما تدخرْ من مالِك ينفعْك.','ما تضيعْ من وقتِك تندمْ عليه.','ما تتلفْ تغرمْ ثمنَه.','ما تنفقْ في الخيرِ تُجزَ به.','إذ ما تفعلْ شرًّا تندمْ.','مهما تنفقْ في الخيرِ يخلفْه اللهُ.','متى يسافرْ أخي أسافرْ معه.','أيانَ تنادِ أجبْك.','أين تذهبْ أصحبْك.','أنّى ينزلْ ذو العلمِ يكرمْ.','حيثما ينزلْ مطرٌ ينمُ الزرعُ.','كيفما تعاملْ صديقَك يعاملْك.','أيَّ بستانٍ تدخلْ تبتهجْ.'],
inquiry:['تقدم لنا أن «إنْ» تجزم فعلين مضارعين يترتب حصول أولهما على حصول الثاني، وهنا نأتي على بقية الأدوات التي تعمل هذا العمل. كل مثال من الأمثلة الأربعة الأولى فيه فعلان مضارعان مجزومان. ومن جهة المعنى حصول أولهما شرط في حصول الثاني، أو حصول الثاني جزاء لوقوع الأول؛ فالمثال الأول يفيد أن الإفراط في الأكل شرط في حصول التخمة، أو أن التخمة جزاء الإفراط. ومن أجل ذلك يسمى الفعل الأول فعل الشرط، ويسمى الثاني جوابه وجزاءه.','وما الذي أوجب جزم الفعلين؟ إذا اختبرنا الأمثلة واحدًا واحدًا لم نجد سببًا سوى دخول «مَن»، فهي التي جزمت وأفادت الشرط؛ ولذلك سميت أداة شرط جازمة. و«مَن» في كل أمثلتها لا تدل إلا على العاقل.','وفي الأمثلة الأربعة الأخيرة فعلان مجزومان أيضًا بدخول «ما»، فهي كـ«مَن» تجزم وتفيد الشرط، غير أنها تدل دائمًا على غير العاقل.','وهناك أدوات أخرى تعمل هذا العمل: «إذ ما» وهي كـ«إنْ». و«مهما» لغير العاقل. و«متى» و«أيان» للزمان. و«أين» و«أنّى» و«حيثما» للمكان. و«كيفما» للحال. و«أيّ» تصلح لجميع هذه المعاني.'],
exercises:[{title:'تمرين 1',tasks:[{ask:'عيّن في العبارات الآتية الأفعال المضارعة المجزومة، وبيّن ما كان منها مجزومًا بالسكون وما كان مجزومًا بحذف حرف العلة، وعيّن فعل الشرط وجوابه في الجمل الشرطية',items:['لم أر صديقي، ولم أسمع أخباره منذ شهرين.','حيثما تمشِ على ضفاف النيل تنشقْ هواءً نقيًّا.','لا تعادِ الناس ولا تشغلْ نفسك بعيوب غيرك.','من يحذرْ عدوَّه ينجُ من أذاه.','متى يأتِ فصل الصيف يرحلْ أهل اليسار إلى شواطئ البحار.','ما تخفِ من أعمالك يعلمْه الله.']}]},{title:'تمرين 2',tasks:[{ask:'أكمل الجمل الشرطية الآتية بذكر جواب الشرط المحذوف، واضبط أواخر الأفعال المضارعة في كل جملة',items:['إن تنم في مجرى الهواء ...','من يسهر كثيرًا ...','أنّى ترسل رسالة بالبريد ...','إذ ما تطع والدك ...','أيُّ صديق تخلص له ...','من يصنع معروفًا ...','ما تغرس من الأشجار ...','متى ينته شهر الصيام ...','حيثما ترافق الأشرار ...','مهما تخف من طباعك ...']}]},{title:'تمرين 3',tasks:[{ask:'أتمم الجمل الآتية بوضع جمل الشرط المحذوفة في المكان الخالي، واضبط أواخر الأفعال المضارعة في كل جملة',items:['مَن ... يعش عزيزًا.','حيثما ... تندم على فعله.','مَن ... تنتقل إليه طباعهم.','ما ... يفسد معدتك.','أنّى ... تجد زرعًا ناضرًا.','إن ... يرجع إليك نشاطك.','متى ... يحضر إلى مصر السائحون.','مَن ... يسلم من أذاهم.','ما ... تنتفع به في زمن الشدة.','مَن ... يؤذ أسنانه.']}]},{title:'تمرين 4',tasks:[{ask:'كوّن ثلاث جمل شرطية يكون فعلا الشرط والجواب في كل منها مضارعين صحيحي الآخر',items:[]},{ask:'كوّن ثلاث جمل شرطية يكون فعلا الشرط والجواب في كل منها مضارعين معتلي الآخر',items:[]},{ask:'كوّن ثلاث جمل شرطية يكون فعل الشرط في كل منها مضارعًا صحيح الآخر والجواب مضارعًا معتل الآخر',items:[]},{ask:'كوّن ثلاث جمل شرطية يكون فعل الشرط في كل منها مضارعًا معتل الآخر والجواب مضارعًا صحيح الآخر',items:[]}]},{title:'تمرين 5',tasks:[{ask:'استعمل أدوات الشرط الآتية في جمل مفيدة',items:['ما','حيثما','أيان','إذ ما','كيفما','أيّ','أين','متى']}]}],exercisesFromBook:true};

