workedExamples:[{sentence:'نجحتْ المجتهدةُ.',meaning:'المعنى: فازت الطالبة المجتهدة.',parse:[['نجحتْ','فعل ماضٍ مبني على الفتح، وتاء التأنيث الساكنة لا محل لها.'],['المجتهدةُ','فاعل مرفوع بالضمة، وعلامة تأنيثه التاء المتحركة.']]},{sentence:'حازتْ ليلى جائزةً.',meaning:'المعنى: نالت ليلى جائزة.',parse:[['حازتْ','فعل ماضٍ مبني على الفتح، وتاء التأنيث الساكنة لا محل لها.'],['ليلى','فاعل مرفوع بضمة مقدّرة على الألف للتعذر، وعلامة تأنيثه ألف التأنيث المقصورة.'],['جائزةً','مفعول به منصوب بالفتحة.']]},{sentence:'ضلّتْ العمياءُ الطريقَ.',meaning:'المعنى: أخطأت المرأة العمياء الطريق.',parse:[['ضلّتْ','فعل ماضٍ مبني على الفتح، وتاء التأنيث الساكنة لا محل لها.'],['العمياءُ','فاعل مرفوع بالضمة، وعلامة تأنيثه ألف التأنيث الممدودة.'],['الطريقَ','مفعول به منصوب بالفتحة.']]}],
