IC.lessonDetails['relative-pronoun']={sentenceExplanation:'«الذي» اسم موصول، و«غلبني» جملة الصلة، والعائد فيها ضمير مستتر يعود على «الذي».',fullParse:[['غلبتُ','فعل ماضٍ مبني على السكون لاتصاله بتاء الفاعل، والتاء ضمير في محل رفع فاعل.'],['الذي','اسم موصول مبني في محل نصب مفعول به.'],['غلبني','فعل ماضٍ مبني على الفتح، والنون للوقاية، والياء ضمير في محل نصب مفعول به، والفاعل ضمير مستتر تقديره «هو» وهو العائد، والجملة صلة الموصول لا محل لها.']],lessonTemplateVersion:1,reviewStatus:R,
learningSteps:[{title:'اعرف الموصول',text:'اسم لا يتم معناه إلا بجملة بعده.'},{title:'اعرف الصلة',text:'الجملة التي بعده وتوضحه.'},{title:'اعرف العائد',text:'ضمير في الصلة يعود على الموصول.'}],
workedExamples:[{sentence:'جاء اللذان غابا.',meaning:'المعنى: حضر الاثنان اللذان غابا.',parse:[['جاء','فعل ماضٍ مبني على الفتح.'],['اللذان','فاعل مبني على الألف في محل رفع، وهو اسم موصول.'],['غابا','غاب فعل ماضٍ، والألف ضمير فاعل مبني على السكون في محل رفع، والجملة صلة، والعائد الألف.']]},{sentence:'أحبُّ الذين علّموني.',meaning:'المعنى: أودّ الذين علّموني.',parse:[['أحبُّ','فعل مضارع مرفوع بالضمة، والفاعل ضمير مستتر تقديره «أنا».'],['الذين','اسم موصول مبني في محل نصب مفعول به.'],['علّموني','علّم فعل ماضٍ مبني على الضم لاتصاله بواو الجماعة، والواو ضمير في محل رفع فاعل وهو العائد، والنون للوقاية، والياء ضمير في محل نصب مفعول به، والجملة صلة لا محل لها.']]},{sentence:'أحسنْ إلى مَن أحسن إليك.',meaning:'المعنى: أحسنْ إلى الذي أحسن إليك.',parse:[['أحسنْ','فعل أمر مبني على السكون، والفاعل ضمير مستتر تقديره «أنتَ».'],['إلى','حرف جر مبني على السكون.'],['مَن','اسم موصول مبني في محل جر بإلى.'],['أحسن إليك','فعل ماضٍ مبني على الفتح، والفاعل ضمير مستتر تقديره «هو» وهو العائد، والجملة صلة لا محل لها.']]}],
guidedPractice:{prompt:'عيّن الموصول والصلة في: رأيتُ الذين فازوا.',hint:'ما الجملة التي توضح المقصود؟',answer:'«الذين» اسم موصول، و«فازوا» صلة، والعائد واو الجماعة.',explanation:'الصلة جملة بعد الموصول تحتوي ضميرًا يعود عليه.'},
summary:['الموصول اسم معرفة تعيّنه جملة بعده تسمى صلة.','يجب أن تشتمل الصلة على عائد.','مَن للعاقل، وما لغير العاقل.'],
commonMistakes:['ترك الموصول بلا صلة.','إغفال العائد في الصلة.'],
bookExamples:['غلبتُ الذي غلبني.','سافرتُ التي كانت عندنا.','حضر اللذان كانا مسافرين.','جاءت اللتان تسكنان أمامنا.','أحبُّ الذين علّموني.','رأيتُ اللائي يشتغلن في المصنع.','أحسنْ إلى مَن أحسن إليك.','لا تأكلْ ما لا تستطيع هضمه.'],
inquiry:['خذ المثال الأول «غلبتُ الذي غلبني»: كلمة «الذي» إذا أُخذت وحدها لا يظهر منها المقصود، لكن الجملة بعدها «غلبني» تعيّنه وتعرّفه للسامع، فهي معرفة بشرط أن توصل بجملة تالية توضح المراد منها. ولذلك تسمى اسمًا موصولًا، وتسمى الجملة الموضحة صلة.','وإذا تأملت الصلة وجدتها تشتمل على ضمير مستتر يعود على اسم الموصول، ولذلك يسمى هذا الضمير عائدًا.','وبقية الكلمات: التي، واللذان، واللتان، والذين، واللاتي، ومَن، وما، كلها معارف لا يتم تعريفها إلا بالجمل المتصلة بها، فهي أسماء موصولة. وبعضها للمذكر، وبعضها للمؤنث، وللمثنى، وللجمع؛ والموصولان «مَن» و«ما» صالحان لكل حال، غير أن «مَن» للعقلاء و«ما» لغير العقلاء.'],
exercises:[{title:'تمرين 1',tasks:[{ask:'بيّن في العبارة الآتية كل اسم موصول وصلته والعائد الذي اشتملت عليه كل صلة',items:['إن الذي يحب وطنه هو من يبذل جهده فيما يرفع قدر أمته التي ينتسب إليها، فالصناع الذين يتقنون أعمالهم يخدمون وطنهم، والنساء اللاتي يربين أبناءهن على الفضيلة يرفعن شأن وطنهن، والتلاميذ الذين يجدّون في دروسهم يبنون مجد أمتهم.']}]},{title:'تمرين 2',tasks:[{ask:'ضع صلة مناسبة لكل اسم موصول في الجمل الآتية',items:['قرأت الكتاب الذي ...','حملت الحقيبة التي ...','هذا هو البيت الذي ...','صاحبْ مَن ...','يحترم التلميذ من ...','كسر القط الزجاجتين اللتين ...','هل زجرت الكلبين الذين ...','قبض الشرطي على الذين ...','هل سمعتَ صراخ اللاتي ...','حكى عليٌّ ما ...']}]},{title:'تمرين 3',tasks:[{ask:'ضع كل كلمة من الكلمات الآتية منعوتة باسم موصول في جملة مفيدة',items:['السرير','المبراة','الخادمات','العلبة','الدواتان','المنزل','الجنود','الحارسان','الغاسلات','التلاميذ']}]},{title:'تمرين 4',tasks:[{ask:'كوّن جملًا فعلية تشتمل كل واحدة منها على اسم موصول، وانتخب له صلة تناسبه من الجمل الآتية',items:['ينبح طول الليل.','يجمعن الصدقات.','تستذكر دروسها.','ركبنا الزورق.','قدما من السفر.','أبوهم مريض.']}]},{title:'تمرين 5',tasks:[{ask:'كوّن ثلاث جمل فعلية يكون الفاعل في كل منها اسمًا موصولًا',items:[]},{ask:'كوّن ثلاث جمل فعلية يكون المفعول به في كل منها اسمًا موصولًا',items:[]},{ask:'كوّن ثلاث جمل اسمية يكون المبتدأ في كل منها اسمًا موصولًا',items:[]},{ask:'كوّن ثلاث جمل يكون اسم كان في كل منها اسمًا موصولًا',items:[]}]},{title:'تمرين 6 في الإنشاء',tasks:[{ask:'خاطب بالجملة الآتية غير الواحد',items:['أنتَ الذي يحسنُ التعبيرَ.']}]},{title:'تمرين 7 في الإعراب',tasks:[{model:true,ask:'نموذج',items:['جاء اللذان غابا.','جاء: فعل ماضٍ مبني على الفتح.','اللذان: فاعل مبني على الألف في محل رفع.','غابا: غاب فعل ماضٍ، والألف ضمير فاعل مبني على السكون في محل رفع، والجملة صلة.']},{ask:'أعرب الجمل الآتية',items:['ودّعتُ اللتين زارتا منزلنا.','الذي يعلمنا مخلصٌ.','إنّ التي تتصدق محبوبةٌ.','رأيتُ الذين فازوا.']}]}],exercisesFromBook:true};

IC.lessonDetails['demonstrative']={sentenceExplanation:'«هذا» اسم إشارة للمفرد المذكر وقع مبتدأ، و«كتابٌ» خبره.',fullParse:[['هذا','اسم إشارة مبني على السكون في محل رفع مبتدأ.'],['كتابٌ','خبر مرفوع بالضمة.'],['نافعٌ','نعت مرفوع بالضمة.']],lessonTemplateVersion:1,reviewStatus:R,
learningSteps:[{title:'انظر إلى المشار إليه',text:'مفرد أو مثنى أو جمع؟ مذكر أو مؤنث؟'},{title:'اختر اسم الإشارة',text:'ذا، ذه، ذان، تان، أولاء.'},{title:'تذكّر المثنى',text:'يرفع بالألف وينصب ويجر بالياء.'}],
workedExamples:[{sentence:'هذه حجرةٌ واسعةٌ.',meaning:'المعنى: أشير إلى حجرة واسعة.',parse:[['هذه','اسم إشارة للمفردة المؤنثة مبني في محل رفع مبتدأ.'],['حجرةٌ','خبر مرفوع بالضمة.'],['واسعةٌ','نعت مرفوع بالضمة.']]},{sentence:'هؤلاء صنّاعٌ ماهرون.',meaning:'المعنى: أشير إلى صناع مهرة.',parse:[['هؤلاء','اسم إشارة لجمع العقلاء مبني على الكسر في محل رفع مبتدأ.'],['صنّاعٌ','خبر مرفوع بالضمة.'],['ماهرون','نعت مرفوع بالواو لأنه جمع مذكر سالم.']]},{sentence:'إنّ هذين فائزان.',meaning:'المعنى: إن هذين الاثنين فائزان.',parse:[['إنّ','حرف توكيد ونصب مبني على الفتح.'],['هذين','اسم إشارة للمثنى المذكر مبني على الياء في محل نصب اسم إنّ.'],['فائزان','خبر إنّ مرفوع بالألف لأنه مثنى.']]}],
guidedPractice:{prompt:'أي اسم إشارة تضع للمثنى المؤنث في الرفع؟',hint:'ذان للمذكر، فما للمؤنث؟',answer:'«تان»، مثل: تان وردتان مفتحتان.',explanation:'«تان» للمثنى المؤنث، وتُرفع بالألف.'},
summary:['اسم الإشارة اسم معرفة يدل على معيّن مشار إليه.','ذا وذه وذان وتان وأولاء.','اسم الإشارة للمثنى يعامل معاملة المثنى.'],
commonMistakes:['الخلط بين «ذا» للمذكر و«ذه» للمؤنث.','نسيان أن اسم الإشارة للمثنى يتغير آخره بالألف والياء.'],
bookExamples:['ذا رجلٌ شريفٌ.','هذا كتابٌ نافعٌ.','ذه امرأةٌ تعتني بأولادها.','هذه حجرةٌ واسعةٌ.','ذان ولدان مهذبان.','إنّ هذين فائزان.','تان وردتان مفتحتان.','إنّ هاتين بنتان مطيعتان.','أولاء تجارٌ صادقون.','هؤلاء صنّاعٌ ماهرون.','أولاء بناتٌ نظيفاتٌ.','هؤلاء تلميذاتٌ لطيفاتٌ.'],
inquiry:['تأمل الأسماء الأولى في الأمثلة: تدل على شيء أو شيئين أو أشياء تشير إليها. فإذا قلت «ذا رجلٌ شريفٌ» فكلمة «ذا» تدل على رجل تشير إليه. فهذه الأسماء معارف لأن المقصود بها معيّن.','وإذا نظرت إلى الأسماء بعدها عرفت ما تخصص له: «ذا» بعدها مفرد مذكر، و«ذه» بعدها مفردة مؤنثة، و«ذين» للمثنى، و«تين» للمثنى المؤنث، و«أولاء» لجمع العقلاء.','وتأتي أسماء الإشارة مرة خالية من «ها» ومرة مسبوقة بها، ومعناه تنبيه السامع وتوجيهه إلى ما سيقوله المتكلم.'],
exercises:[{title:'تمرين 1',tasks:[{ask:'أشر إلى سبعة أشياء بحجرة الدراسة، مع التعبير بجمل تامة',items:[]},{ask:'أشر إلى سبعة أشياء على مائدة الطعام، مع التعبير بجمل تامة',items:[]},{ask:'أشر إلى سبعة أشياء في غرفة النوم، مع التعبير بجمل تامة',items:[]},{ask:'أشر إلى سبعة أشياء في الشارع، مع التعبير بجمل تامة',items:[]}]},{title:'تمرين 2',tasks:[{ask:'أشر إلى مدلول الكلمات الآتية، مع التعبير بجمل تامة',items:['الحصان','الهرمان','التلاميذ','المسطرة','الحمامة','السيدات','القمر','القلمان','اللاعبون','الكراسات']}]},{title:'تمرين 3',tasks:[{ask:'اجعل اسم الإشارة في الجملة الآتية للمفردة، ثم المثنى، والجمع بنوعيهما',items:['هذا التلميذ نجح في امتحانه.']}]},{title:'تمرين 4',tasks:[{ask:'اجعل كل اسم من الأسماء الآتية خبرًا لمبتدأ، بحيث يكون المبتدأ اسم إشارة',items:['نافع','مجتهدات','شامخات','مطيعة','كرماء','كريمة','طويلان','مسافرات','مسرورون','واسعتان']}]},{title:'تمرين 5',tasks:[{ask:'ضع اسم إشارة ومشارًا إليه قبل كل جملة من الجمل الآتية',items:['... يسبح في الماء.','... أنقذ الغريق.','... ينصرون الفضيلة.','... راكبو الطيارة.','... نالت الجائزة.','... ركب السيارة.','... يحرسان الحقل.','... أتقنا الطبخ.','... ثوبها نظيف.','... تجمعان الأزهار.','... يبحثون عن عمل نافع.','... رفعن قدر وطنهن.']}]},{title:'تمرين 6',tasks:[{ask:'كوّن ست جمل فعلية، يكون المفعول به في كل واحدة منها اسم إشارة مع اختلاف نوع المشار إليه في كل جملة',items:[]}]},{title:'تمرين 7',tasks:[{ask:'كوّن ثلاث جمل اسمية المبتدأ فيها اسم إشارة للمفرد المذكر',items:[]},{ask:'كوّن ثلاث جمل اسمية المبتدأ فيها اسم إشارة للمفردة المؤنثة',items:[]},{ask:'كوّن ثلاث جمل اسمية المبتدأ فيها اسم إشارة للمثنى المذكر',items:[]},{ask:'كوّن ثلاث جمل اسم أصبح فيها اسم إشارة للمثنى المؤنث',items:[]},{ask:'كوّن ثلاث جمل اسم لعل فيها اسم إشارة لجماعة الذكور',items:[]},{ask:'كوّن ثلاث جمل فيها اسم إشارة لجماعة الإناث مسبوق بحرف جر',items:[]}]},{title:'تمرين 8 في الإعراب',tasks:[{model:true,ask:'نموذج',items:['هذا كتابٌ.','هذا: مبتدأ مبني على السكون في محل الرفع.','كتابٌ: خبر المبتدأ مرفوع بالضمة.']},{ask:'أعرب ما يأتي',items:['خذ هذه.','انظر إلى هاتين.','هؤلاء مجتهدون.','هذان قلمان.']}]}],exercisesFromBook:true};

IC.lessonDetails['passive-agent']={sentenceExplanation:'«فُتِحَ» فعل ماضٍ مبني للمجهول، و«البابُ» نائب فاعل مرفوع حلّ محل الفاعل المحذوف.',fullParse:[['فُتِحَ','فعل ماضٍ مبني للمجهول مبني على الفتح.'],['البابُ','نائب فاعل مرفوع بالضمة.']],lessonTemplateVersion:1,reviewStatus:R,
learningSteps:[{title:'احذف الفاعل',text:'استغنِ عن الفاعل واجعل المفعول به في موضعه.'},{title:'غيّر شكل الفعل',text:'الماضي: ضم الأول وكسر ما قبل الآخر. المضارع: ضم الأول وفتح ما قبل الآخر.'},{title:'ارفع نائب الفاعل',text:'وإن كان مؤنثًا فأنّث الفعل.'}],
workedExamples:[{sentence:'يُركَبُ الحصانُ.',meaning:'المعنى: يركب أحدٌ الحصان.',parse:[['يُركَبُ','فعل مضارع مبني للمجهول مرفوع بالضمة.'],['الحصانُ','نائب فاعل مرفوع بالضمة.']]},{sentence:'قُطِفَتِ الزهرةُ.',meaning:'المعنى: قطف أحدٌ الزهرة.',parse:[['قُطِفَتِ','فعل ماضٍ مبني للمجهول مبني على الفتح، والتاء للتأنيث.'],['الزهرةُ','نائب فاعل مرفوع بالضمة.']]},{sentence:'تُهذَّبُ البنتُ.',meaning:'المعنى: تُؤدَّب البنت.',parse:[['تُهذَّبُ','فعل مضارع مبني للمجهول مرفوع بالضمة، والتاء للتأنيث.'],['البنتُ','نائب فاعل مرفوع بالضمة.']]}],
guidedPractice:{prompt:'ابنِ للمجهول: أكلَ الفأرُ الجبنَ.',hint:'احذف الفاعل وارفع المفعول به، واضمم أول الفعل واكسر ما قبل آخره.',answer:'أُكِلَ الجبنُ.',explanation:'«الجبنُ» نائب فاعل مرفوع.'},
summary:['نائب الفاعل اسم مرفوع حلّ محل الفاعل المحذوف.','الماضي: يضم أوله ويكسر ما قبل آخره.','المضارع: يضم أوله ويفتح ما قبل آخره.','إن كان نائب الفاعل مؤنثًا أُنّث الفعل.'],
commonMistakes:['إبقاء نائب الفاعل منصوبًا: «أُكِلَ الجبنَ».','تغيير الفعل بالضم والكسر دون حذف الفاعل.'],
bookExamples:['فتح الولدُ البابَ ← فُتِحَ البابُ.','أكل الفأرُ الجبنَ ← أُكِلَ الجبنُ.','كسرتِ الهرةُ الإناءَ ← كُسِرَ الإناءُ.','قطفتِ البنتُ الزهرةَ ← قُطِفَتِ الزهرةُ.','تجمعُ النملةُ الغذاءَ ← يُجمَعُ الغذاءُ.','يركبُ عليٌّ الحصانَ ← يُركَبُ الحصانُ.','تحلبُ المرأةُ البقرةَ ← تُحلَبُ البقرةُ.','تهذّبُ المعلمةُ البنتَ ← تُهذَّبُ البنتُ.'],
inquiry:['انظر إلى الأمثلة الأربعة الأولى: في كل مثال فعل ماضٍ وفاعل ومفعول به. وقابل كل مثال بالذي أمامه، تجد المعنى متحدًا. وفي الثاني تغيّر شكل الفعل: صار حرفه الأول مضمومًا، والحرف الذي قبل آخره مكسورًا، وحُذف الفاعل وناب عنه المفعول به، فأصبح مرفوعًا بعد أن كان منصوبًا.','وفي الأمثلة الأربعة الأخرى تغيّر المضارع: صار أوله مضمومًا والحرف الذي قبل آخره مفتوحًا، وحُذف الفاعل وناب عنه المفعول به فصار مرفوعًا. هذا المفعول به الذي صار مرفوعًا يسمى نائب الفاعل.','وإذا تأملت الأمثلة الرابع والسابع والثامن علمتَ أن نائب الفاعل إذا كان مؤنثًا كان الفعل مؤنثًا أيضًا.'],
exercises:[{title:'تمرين 1',tasks:[{ask:'استخرج نائب الفاعل وفعله من العبارة الآتية',items:['تصنع القهوة من البن، وطريقة ذلك أن يسكب الماء في الإناء، ثم يوضع على النار، فإذا غلى الماء رفع الإناء وطرح فيه جزء من البن، وقلّب البن بملعقة ليمتزج بالماء، ثم يقرّب الإناء من النار ثانية لينضج ما فيه، وتمزج القهوة بسكر أحيانًا وكثيرًا ما تشرب بدونه.']}]},{title:'تمرين 2',tasks:[{ask:'حوّل الأفعال التي في الجمل الآتية إلى أفعال مبنية للمجهول، مع بقاء كل فعل في جملته',items:['شرب الولدان اللبن.','قتل الصائد الذئب.','خمش القط أخاك.','فهمنا درسنا.','مدحنا المعلم.','نفعني الصدق.','يدّخر المقتصد المال.','يجمع الأولاد القطن.','يسقي الحوذيُّ الحصانين.','نعبد الله.','يحترمك.','يخفضني الكذب.']}]},{title:'تمرين 3',tasks:[{ask:'ضع نائب فاعل مناسبًا لكل فعل من الأفعال الآتية، بعد بنائه للمجهول',items:['يزرع','حبس','نظر','تنظف','ترحم','شكرت','نصر','يسمع','يعظّم','تساعد']}]},{title:'تمرين 4',tasks:[{ask:'ضع الأسماء الآتية في جمل، بحيث يكون كل اسم منها نائب فاعل',items:['القاهرة','الغصن','الورد','المائدة','المجتهدون','الطعام','المدرسة','الشارع','التلاميذ','المذنب']}]},{title:'تمرين 5',tasks:[{ask:'كوّن جملتين يكون نائب الفاعل فيهما مرة مثنى، ومرة جمع مذكر سالمًا، وأخرى اسمًا موصولًا، ورابعة ضميرًا متصلًا',items:[]}]},{title:'تمرين 6 في الإنشاء',tasks:[{ask:'صف كل ما يعمل لكتابة رسالة، من أول إعداد أدوات الكتابة إلى أن تصل بالبريد إلى يد المرسَل إليه، مستعملًا أفعالًا مبنية للمجهول',items:[]}]},{title:'تمرين 7 في الإعراب',tasks:[{model:true,ask:'نموذج',items:['ذُبِحَتِ الشاةُ.','ذبحت: ذبح فعل ماضٍ مبني للمجهول والتاء حرف التأنيث.','الشاة: نائب فاعل مرفوع بالضمة.']},{ask:'أعرب ما يأتي',items:['سُرِقَ المالُ.','لم تُسبَقْ سيارتنا.']}]}],exercisesFromBook:true};

