IC.lessonDetails['continuity-verbs']={sentenceExplanation:'«ما زال» دخلت على «الحرُّ شديدٌ» فرفعت المبتدأ ونصبت الخبر، وأفادت استمرار شدة الحر.',fullParse:[['ما','حرف نفي مبني على السكون.'],['زال','فعل ماضٍ ناقص مبني على الفتح.'],['الحرُّ','اسم زال مرفوع بالضمة.'],['شديدًا','خبر زال منصوب بالفتحة.']],lessonTemplateVersion:1,reviewStatus:R,
learningSteps:[{title:'انتبه للأداة',text:'ما أو لا أو لم قبل زال وأخواتها.'},{title:'ارفع الاسم',text:'المبتدأ يصير اسمها مرفوعًا.'},{title:'انصب الخبر',text:'الخبر يبقى منصوبًا.'}],
workedExamples:[{sentence:'ما انفكتِ النارُ مشتعلةً.',meaning:'المعنى: النار ما زالت مشتعلة.',parse:[['ما','حرف نفي مبني على السكون.'],['انفكتْ','فعل ماضٍ ناقص مبني على الفتح، وتاء التأنيث الساكنة لا محل لها.'],['النارُ','اسم انفك مرفوع بالضمة.'],['مشتعلةً','خبر انفك منصوب بالفتحة.']]},{sentence:'ما انفكَّ القضاةُ عادلين.',meaning:'المعنى: ما زال القضاة عادلين.',parse:[['ما','حرف نفي مبني على السكون.'],['انفكَّ','فعل ماضٍ ناقص مبني على الفتح.'],['القضاةُ','اسم انفك مرفوع بالضمة.'],['عادلين','خبر انفك منصوب بالياء لأنه جمع مذكر سالم.']]},{sentence:'لا تقرأ ما دام النورُ ضئيلًا.',meaning:'المعنى: لا تقرأ مدة بقاء النور ضعيفًا.',parse:[['ما','حرف مبني على السكون يدل على الزمان.'],['دام','فعل ماضٍ ناقص مبني على الفتح.'],['النورُ','اسم دام مرفوع بالضمة.'],['ضئيلًا','خبر دام منصوب بالفتحة.']]}],
guidedPractice:{prompt:'عيّن اسم «ما فتئ» وخبرها في: ما فتئ التاجرُ صادقًا.',hint:'ما المبتدأ في الجملة الأصلية؟',answer:'«التاجرُ» اسم ما فتئ مرفوع بالضمة، و«صادقًا» خبرها منصوب بالفتحة.',explanation:'الفعل رفع الأول ونصب الثاني.'},
summary:['ما زال وما برح وما انفك وما فتئ تفيد استمرار الاتصاف.','«ما دام» تبيّن مدة ما قبلها.','كلها ترفع المبتدأ وتنصب الخبر مثل كان.'],
commonMistakes:['إعراب الاسم فاعلًا والخبر مفعولًا به.','حذف أداة النفي من أول الفعل.'],
bookExamples:['ما زال الحرُّ شديدًا.','ما زال المهذبُ محبوبًا.','ما برح المريضُ نائمًا.','ما برح المطرُ هاطلًا.','ما انفكت النارُ مشتعلةً.','ما انفك القضاةُ عادلين.','ما فتئ التاجرُ صادقًا.','تحترمُ ما دام خلقُكَ كريمًا.','لا تقرأ ما دام النورُ ضئيلًا.'],
inquiry:['أمثلة القسم الأول جمل اسمية من مبتدأ وخبر، وأمثلة القسم الثاني هي الجمل نفسها مع زيادة ما زال أو ما برح أو ما انفك أو ما فتئ أو ما دام.','فإذا بحثنا عما أحدثته هذه الأفعال وجدنا أنها رفعت المبتدأ ونصبت الخبر، فهي تشبه «كان»، وهي في الحقيقة بقية أخوات كان.','والأربعة الأولى مسبوقة بحرف نفي، و«ما دام» مسبوقة بـ«ما» الدالة على الوقت. ويعمل عملها مضارعها، وليس لها فعل أمر، ولا يستعمل لـ«دام» إلا الماضي.','ومن يقول «ما زال الحرُّ شديدًا» يخبر باستمرار الشدة، ومثلها ما برح وما انفك وما فتئ. ومن يقول «تحترم ما دام خلقك كريمًا» يبين المدة التي تحترم فيها.'],
exercises:[{title:'تمرين 1',tasks:[{ask:'عيّن الاسم والخبر في كل جملة من الجمل الآتية',items:['لا يفتأ الكذابُ غائبًا.','ما فتئ أخونا صابرًا.','ألا تزال صابرًا؟','كلْ ما دمتَ جائعًا.','لا ينفك النسيمُ عليلًا.','ما زال الهواءُ عليلًا.','لا أكلمك ما دمتَ معاندًا.','لا تزال الشمسُ مشرقةً.','ما برح الكتابُ مفقودًا.','ما انفكت السماءُ غائمةً.']}]},{title:'تمرين 2',tasks:[{ask:'أدخل على كل جملة من الجمل الآتية فعلًا من أفعال الاستمرار مع استيفائها جميعها، واشكل آخر الاسم والخبر',items:['مصراعا الباب مقفلان.','المحسن أبوك.','العمال متعطلون.','الأمهات شفيقات.','الصدقة نافعة.','السوق مزدحمة.']}]},{title:'تمرين 3',tasks:[{ask:'ضع جملة مناسبة قبل كل تركيب من التراكيب الآتية',items:['... ما دام البرد قارسًا.','... ما دامت مجتهدةً.','... ما دام أبي نائمًا.','... ما دام الحصان جامحًا.','... ما دمتَ سفيهًا.','... ما دمتُ حيًّا.']}]},{title:'تمرين 4',tasks:[{ask:'ضع فعلًا مناسبًا من الأفعال التي ترفع المبتدأ وتنصب الخبر في المكان الخالي',items:['انتهى الامتحان و... النتيجة مجهولة.','زالت الحمّى و... المريض ضعيفًا.','تصدّق على الفقراء ... قادرًا.','لا تتعرض للبرد ... مريضًا.','صفر القطار و... أخي غائبًا.','أمسى الليل ... القمر منيرًا.']}]},{title:'تمرين 5',tasks:[{ask:'كوّن ثلاث جمل أول كل واحدة منها «ما انفك»',items:[]},{ask:'كوّن ثلاث جمل أول كل واحدة منها «لا يزال»',items:[]},{ask:'كوّن ثلاث جمل تشمل كل واحدة منها على «ما دام»',items:[]}]},{title:'تمرين 6',tasks:[{ask:'كوّن جملة مبدوءة بفعل من أفعال الاستمرار، اسمه اسم موصول لجماعة الذكور وخبره مضاف',items:[]}]},{title:'تمرين 7 في الإعراب',tasks:[{model:true,ask:'نموذج',items:['ما برح السفرُ مفيدًا.','ما: حرف نفي مبني على السكون.','برح: فعل ماضٍ مبني على الفتح.','السفرُ: اسم برح مرفوع بالضمة.','مفيدًا: خبر برح منصوب بالفتحة.']},{ask:'أعرب ما يأتي',items:['لا يزال الصدقُ سبيلَ النجاةِ.','ما فتئ أخوك مجتهدًا.','اسكتْ ما دام السكوتُ نافعًا.']}]}],exercisesFromBook:true};

