learningSteps:[{title:'اسأل «متى؟»',text:'إن كان الجواب زمنًا منصوبًا فهو ظرف زمان.'},{title:'اسأل «أين؟»',text:'إن كان الجواب مكانًا منصوبًا فهو ظرف مكان.'},{title:'أعربه',text:'ظرف زمان أو مكان منصوب بالفتحة.'}],
