IC.lessonDetails['nasikh-predicate']={sentenceExplanation:'اسم «كان» هو «المريضُ»، وخبرها جملة فعلية «يتألمُ» في محل نصب.',fullParse:[['كان','فعل ماضٍ ناقص مبني على الفتح.'],['المريضُ','اسم كان مرفوع بالضمة.'],['يتألمُ','فعل مضارع مرفوع بالضمة، والفاعل ضمير مستتر تقديره «هو»، والجملة في محل نصب خبر كان.']],lessonTemplateVersion:1,reviewStatus:R,
learningSteps:[{title:'حدّد الناسخ واسمه',text:'كان وأخواتها أو إنّ وأخواتها، ثم اسمها.'},{title:'انظر إلى الخبر',text:'مفرد؟ جملة؟ شبه جملة؟'},{title:'احكم على المحل',text:'نصب لخبر كان، ورفع لخبر إنّ.'}],
workedExamples:[{sentence:'أصبح الوردُ رائحتُه جميلةٌ.',meaning:'المعنى: صارت رائحة الورد جميلة.',parse:[['أصبح','فعل ماضٍ ناقص مبني على الفتح.'],['الوردُ','اسم أصبح مرفوع بالضمة.'],['رائحتُه','مبتدأ مرفوع بالضمة، وهو مضاف، والهاء ضمير في محل جر مضاف إليه.'],['جميلةٌ','خبر المبتدأ مرفوع بالضمة، والجملة الاسمية في محل نصب خبر أصبح.']]},{sentence:'إنّ الحياءَ من الإيمانِ.',meaning:'المعنى: الحياء من الإيمان.',parse:[['إنّ','حرف توكيد ونصب مبني على الفتح.'],['الحياءَ','اسم إنّ منصوب بالفتحة.'],['من','حرف جر مبني على السكون.'],['الإيمانِ','اسم مجرور بـ«من»، والجار والمجرور في محل رفع خبر إنّ.']]},{sentence:'لعلَّ الغائبَ يعودُ.',meaning:'المعنى: أرجو أن يعود الغائب.',parse:[['لعلَّ','حرف ترجٍّ ونصب مبني على الفتح.'],['الغائبَ','اسم لعل منصوب بالفتحة.'],['يعودُ','فعل مضارع مرفوع بالضمة، والفاعل ضمير مستتر تقديره «هو»، والجملة في محل رفع خبر لعل.']]}],
guidedPractice:{prompt:'عيّن نوع الخبر في: أصبح الطلُّ فوقَ الأزهارِ.',hint:'ما الذي جاء بعد اسم أصبح؟',answer:'الخبر شبه جملة (ظرف مكان «فوقَ») في محل نصب خبر أصبح.',explanation:'الظرف شبه جملة.'},
summary:['خبر النواسخ قد يكون مفردًا أو جملة أو شبه جملة.','خبر كان وأخواتها في محل نصب.','خبر إنّ وأخواتها في محل رفع.'],
commonMistakes:['البحث عن خبر مفرد فقط.','نسيان أن محل جملة خبر كان نصب لا رفع.'],
bookExamples:['كان المريضُ يتألمُ.','كان الشتاءُ بردُه شديدٌ.','كان الماءُ في الكوبِ.','كان الحارسُ خلفَ البابِ.','أصبح الطائرُ يغني.','أصبح الوردُ رائحتُه جميلةٌ.','أصبح الكسلانُ في حيرةٍ.','أصبح الطلُّ فوقَ الأزهارِ.','إنّ المجدَ ينفعُ نفسَه.','إنّ الولدَ زينتُه الأدبُ.','إنّ الحياءَ من الإيمانِ.','إنّ الحكمَ بعدَ التجربةِ.','لعل الغائبَ يعودُ.','لعل الامتحانَ أسئلتُه سهلةٌ.','لعل محمدًا في المنزلِ.','لعل المبراةَ فوقَ الكرسيِّ.'],
inquiry:['عرفتَ في الدرس السابق أن خبر المبتدأ كما يكون مفردًا يكون جملة وشبه جملة. وإذا بحثت في هذه الأمثلة على النحو نفسه عرفت أن خبر كان وأصبح، وخبر إنّ ولعل، كما يكون كل منهما مفردًا يكون جملة وشبه جملة.','وقد اقتصرنا على فعلين من كان وأخواتها وعلى حرفين من إنّ وأخواتها؛ لأنك تستطيع أن تقيس عليها بقية الأفعال والحروف الناسخة.'],
exercises:[{title:'تمرين 1',tasks:[{ask:'بيّن نوع أخبار كان وأخواتها، وإنّ وأخواتها في العبارة الآتية',items:['كان الناس يظنون أنّ فنّ الطيران نجاحه مستحيل، وصاروا يسخرون من كل من يظل يعمل لتحقيقه؛ لأنهم يرون أن الإنسان عزمه محدود، وأنه لن يزال على حالته التي خُلق عليها ما دام لم يخلق كالطائر، ولكنّ المخترعين آمالهم بعيدة، فثابروا حتى تمّ نجاح الطيران، وأصبح من أحسن وسائل الانتقال، واستطاع الطيارون أن يعبروا المحيط الأطلنطي من أمريكا إلى أوروبا بلا خوف كأنهم فوق بساط سليمان.']}]},{title:'تمرين 2',tasks:[{ask:'ضع جملة فعلية لتكون خبرًا لكان أو إحدى أخواتها في كل مما يأتي',items:['كان المطر ...','أمست الناجحات ...','لا ينفك الكلب ...','يصبح الصناع ...','ما زال الجهل ...','أضحت المريضة ...','ما برح المزاح ...','ليس الحسد ...','يظل الحصانان ...','ما فتئ الصدق ...','لا أكلمك ما دمتَ ...','صار الدم ...']}]},{title:'تمرين 3',tasks:[{ask:'ضع جملة اسمية لتكون خبرًا لكان أو إحدى أخواتها في كل مما يأتي',items:['لم يكن الشارع ...','أمسى الفلاحون ...','ما برحت الممرضات ...','أصبحت الحديقة ...','بات السجينان ...','ما فتئ المخترع ...','أضحى الصائم ...','صار المصباح ...','ما انفك الحزين ...','ظلت النافورة ...','ما زال العلماء ...','لا ينبت الزرع ما دامت الأرض ...']}]},{title:'تمرين 4',tasks:[{ask:'ضع جملة فعلية لتكون خبرًا لإنّ أو إحدى أخواتها في كل مما يأتي',items:['إن العلم ...','أنت ذكيٌّ لكنك ...','ثق أن القطار ...','ليت الموتى ...','كأن الببغاء ...','لعل الجاهلات ...']}]},{title:'تمرين 5',tasks:[{ask:'ضع جملة اسمية لتكون خبرًا لإنّ أو إحدى أخواتها في كل مما يأتي',items:['إن القمر ...','ليت البئر ...','أبي طبيب لكن محمدًا ...','كأن البحر ...','بلغني أن الصحراء ...','لعل الممثلين ...']}]},{title:'تمرين 6',tasks:[{ask:'ضع جارًّا ومجرورًا ليكونا خبرًا في كل جملة من الجمل الآتية',items:['كان الخادم ...','أمسى الشرطي ...','لا ينفك المجرم ...','إن الماء ...','ليت النقود ...','كأن ذراعي الأسد ...']}]},{title:'تمرين 7',tasks:[{ask:'ضع ظرفًا ليكون خبرًا في كل جملة من الجمل الآتية',items:['أصبح التلميذ ...','علمت أن الامتحان ...','أضحت الشمس ...','ظل الطائر ...','لعل الاحتفال ...','كتابك عندي لكن كتابي ...']}]},{title:'تمرين 8',tasks:[{ask:'كوّن خمس جمل تشتمل كل منها على فعل من أخوات كان، والخبر جملة فعلية',items:[]},{ask:'كوّن خمس جمل تشتمل كل منها على فعل من أخوات كان، والخبر جملة اسمية',items:[]},{ask:'كوّن خمس جمل تشتمل كل منها على فعل من أخوات كان، والخبر جار ومجرور',items:[]},{ask:'كوّن خمس جمل تشتمل كل منها على فعل من أخوات كان، والخبر ظرف',items:[]},{ask:'كوّن خمس جمل تشتمل كل منها على حرف من أخوات إنّ، والخبر جملة فعلية',items:[]},{ask:'كوّن خمس جمل تشتمل كل منها على حرف من أخوات إنّ، والخبر جملة اسمية',items:[]},{ask:'كوّن خمس جمل تشتمل كل منها على حرف من أخوات إنّ، والخبر جار ومجرور',items:[]},{ask:'كوّن خمس جمل تشتمل كل منها على حرف من أخوات إنّ، والخبر ظرف',items:[]}]}],exercisesFromBook:true};

IC.lessonDetails['an-opening']={sentenceExplanation:'«أنّ» واسمها وخبرها في «أنك مطيعٌ» يحلّون محل المصدر «إطاعتك»، وهو فاعل «يسرّني».',fullParse:[['يسرّني','فعل مضارع مرفوع بالضمة، والنون للوقاية، والياء ضمير في محل نصب مفعول به.'],['أنّ','حرف توكيد ونصب مبني على الفتح.'],['الكاف','اسم أنّ ضمير متصل مبني في محل نصب.'],['مطيعٌ','خبر أنّ مرفوع بالضمة.'],['المصدر المؤول','من أنّ واسمها وخبرها في محل رفع فاعل، وتقديره: يسرني إطاعتك.']],lessonTemplateVersion:1,reviewStatus:R,
learningSteps:[{title:'جرّب المصدر',text:'ضع مصدرًا صريحًا مكان أنّ ومعموليها.'},{title:'اختبر المعنى',text:'إن بقي المعنى سليمًا فالهمزة مفتوحة.'},{title:'أعرب المصدر المؤول',text:'فاعل، مفعول به، نائب فاعل، أو مجرور بحرف جر.'}],
workedExamples:[{sentence:'علمتُ أنّ القطارَ متحركٌ.',meaning:'المعنى: علمتُ تحرّك القطار.',parse:[['علمتُ','فعل ماضٍ مبني على السكون لاتصاله بتاء الفاعل، والتاء ضمير في محل رفع فاعل.'],['أنّ','حرف توكيد ونصب.'],['القطارَ','اسم أنّ منصوب بالفتحة.'],['متحركٌ','خبر أنّ مرفوع بالضمة.'],['المصدر المؤول','في محل نصب مفعول به.']]},{sentence:'أُعلنَ أنّ الحمى منتشرةٌ.',meaning:'المعنى: أُعلن انتشار الحمى.',parse:[['أُعلنَ','فعل ماضٍ مبني للمجهول مبني على الفتح.'],['أنّ','حرف توكيد ونصب.'],['الحمى','اسم أنّ منصوب بفتحة مقدّرة على الألف.'],['منتشرةٌ','خبر أنّ مرفوع بالضمة.'],['المصدر المؤول','في محل رفع نائب فاعل.']]},{sentence:'وثقتُ من أنّ التاجرَ صادقٌ.',meaning:'المعنى: وثقتُ من صدق التاجر.',parse:[['وثقتُ','فعل ماضٍ مبني على السكون لاتصاله بتاء الفاعل، والتاء ضمير في محل رفع فاعل.'],['من','حرف جر مبني على السكون.'],['أنّ التاجرَ صادقٌ','المصدر المؤول في محل جر بحرف الجر «من»، وتقديره: صدق التاجر.']]}],
guidedPractice:{prompt:'ما موقع المصدر المؤول وتقديره في: أتمنى أن القمرَ طالعٌ؟',hint:'ضع مصدرًا صريحًا مكان أن ومعموليها.',answer:'مفعول به، وتقديره: أتمنى طلوع القمر.',explanation:'المصدر المؤول وقع بعد فعل متعدٍّ فهو مفعول به.'},
summary:['تفتح همزة أنّ إذا حلّت هي واسمها وخبرها محل المصدر.','المصدر المكوّن منها يسمى مصدرًا مؤولًا.','يكون فاعلًا أو مفعولًا به أو نائب فاعل أو مجرورًا بحرف جر.'],
commonMistakes:['كسر همزة أنّ حيث يصح وضع المصدر مكانها.','إهمال إعراب المصدر المؤول بعد إعراب أجزائه.'],
bookExamples:['يسرّني أنك مطيعٌ. (يسرني إطاعتك)','يؤلمني أن الغبارَ كثيرٌ. (يؤلمني كثرة الغبار)','أتمنى أن القمرَ طالعٌ. (أتمنى طلوع القمر)','علمتُ أن القطارَ متحركٌ. (علمتُ تحرك القطار)','ظُنَّ أن النتيجةَ حسنةٌ. (ظُنَّ حسن النتيجة)','عُرِفَ أن السارقَ جريءٌ. (عُرِفَ جراءة السارق)','أعطيتُه لأنه فقيرٌ. (أعطيتُه لفقره)','لا شكَّ في أنّ الأدبَ واجبٌ. (لا شكَّ في وجوب الأدب)'],
inquiry:['قبل دراسة الأمثلة لا بد أن نفهم كلمة واحدة: «المصدر». الفعل يدل على حصول عمل في زمن خاص، وهذا العمل الذي يدل عليه الفعل يسمى مصدرًا؛ فمصدر لعب: اللعب، ومصدر استغفر: الاستغفار، ومصدر اجتمع: الاجتماع.','قابل بين كل مثال والجملة التي أمامه: وُضع في كل جملة مصدر مكان أنّ واسمها وخبرها، وهذا المصدر مفهوم من خبر أنّ؛ فإطاعة وكثرة وطلوع وتحرك مفهومة من مطيع وكثير وطالع ومتحرك. ولم يتغير المعنى.','وهذا المصدر لم يُذكر صريحًا فسُمّي مصدرًا مؤولًا. وهمزة أنّ في هذه الأمثلة مفتوحة دائمًا.','وإعراب المصدر المؤول في الأمثلة: فاعل في الأولين، ومفعول به في الثانيين، ونائب فاعل في الثالثين، ومجرور بحرف جر في الرابعين.'],
exercises:[{title:'تمرين 1',tasks:[{ask:'هات مصدر كل فعل من الأفعال الآتية، وضع أربعة من هذه المصادر في جمل تامة',items:['يجلس','قدّم','يتصرف','يساعد','اتفق','صاد','أحسن','استعدّ','يبكي','يعود','تسابق','يمرض']}]},{title:'تمرين 2',tasks:[{ask:'هات الفعل الماضي المأخوذ من كل مصدر من المصادر الآتية، واستعمل ثلاثة أفعال في جمل تامة',items:['الشكر','الاستفهام','الانطلاق','الخروج','المشي','المشاهدة','التسليم','الفرح','الكتابة','التدحرج','التباهي','الخوف']}]},{title:'تمرين 3',tasks:[{ask:'ضع بدل «أنّ» ومعموليها مصدرًا صريحًا في كل جملة من الجمل الآتية، وبيّن موقعه من الإعراب',items:['ظنّ الطفل أن القمر صغير.','وجدتُ أن التأخير مضرّ.','وثقتُ من أن التاجر صادق.','يحسب البخيل أن المال خالد.','أُخبرتُ بأن المسافر قدم.','سرّ عليًّا أنه ناجح.']}]},{title:'تمرين 4',tasks:[{ask:'اجعل المصدر الصريح في كل جملة من الجمل الآتية مصدرًا مؤولًا من «أنّ» واسمها وخبرها',items:['يؤلمني احتياج البائسين.','أخشى افتراس الأسد.','علمتُ إفادة الدواء.','عجبتُ من احتيال الثعلب.','سُرّ التلميذ بنجاحه.','سُررتُ من سرعة القطار.','اشتهر ذكاء الفيل.','فرحتُ بجمال الدار.','أدهشني صبر الجمل.','أحزنني إهمالك.']}]},{title:'تمرين 5',tasks:[{ask:'بيّن سبب فتح همزة «أنّ» في الجمل الآتية ومواقع المصادر المؤولة من الإعراب',items:['أُعلن أن الحمى منتشرة.','يزعج الملاحَ أن الريح شديدة.','أغضبك أن القلم مكسور.','أعتقد أن الله قادر.','حزن الفلاح لأن النيل منخفض.','عُلم أن الخبر صحيح.']}]},{title:'تمرين 6',tasks:[{ask:'كوّن ثلاث جمل يكون المصدر المؤول من «أنّ» ومعموليها في كل منها مفعولًا به',items:[]},{ask:'كوّن ثلاث جمل يكون المصدر المؤول في كل منها فاعلًا',items:[]},{ask:'كوّن ثلاث جمل يكون المصدر المؤول في كل منها مجرورًا بحرف جر',items:[]},{ask:'كوّن ثلاث جمل يكون المصدر المؤول في كل منها نائب فاعل',items:[]}]},{title:'تمرين 7 في الإعراب',tasks:[{model:true,ask:'نموذج',items:['أرجو أنَّ أملي يتحقق.','أرجو: فعل مضارع مرفوع بضمة مقدرة على الواو، والفاعل ضمير مستتر تقديره أنا.','أنَّ: حرف توكيد مبني على الفتح.','أملي: أمل اسم أنّ منصوب بفتحة مقدرة لوجود الكسر المناسب للياء، والياء ضمير مضاف إليه مبني على السكون في محل جر.','يتحقق: فعل مضارع مرفوع بالضمة، والفاعل ضمير مستتر تقديره هو، والجملة من الفعل والفاعل في محل رفع خبر أنّ، والمصدر المؤول من أنّ واسمها وخبرها مفعول به للفعل أرجو، وتقديره أرجو تحقق أملي.']},{ask:'أعرب الجمل الآتية',items:['أتمنى أنَّ الحياة سعيدة.','أُشيع أنَّ الجراد رحل عن مصر.','يؤلمني أنك متألم.','وثقتُ بأنك ماهر.']}]}],exercisesFromBook:true};

