IC.lessonDetails['hal-types']={sentenceExplanation:'جملة «المضيفُ غائبٌ» اسمية وقعت حالًا من «الضيوف»، ورابطها الواو.',fullParse:[['حضرَ','فعل ماضٍ مبني على الفتح.'],['الضيوفُ','فاعل مرفوع بالضمة، وهو صاحب الحال.'],['والمضيفُ','الواو واو الحال، و«المضيفُ» مبتدأ مرفوع بالضمة.'],['غائبٌ','خبر مرفوع بالضمة، والجملة الاسمية في محل نصب حال.']],lessonTemplateVersion:1,reviewStatus:R,
learningSteps:[{title:'عيّن الحال',text:'ما الذي بيّن هيئة الفاعل أو المفعول به؟'},{title:'حدّد صورتها',text:'مفرد أم جملة أم ظرف أم جار ومجرور؟'},{title:'ابحث عن الرابط',text:'إن كانت جملة: واو أم ضمير أم هما؟'}],
workedExamples:[{sentence:'ذهبَ الجاني تحرسُه الجنودُ.',meaning:'المعنى: ذهب الجاني وهو محروس.',parse:[['ذهبَ','فعل ماضٍ مبني على الفتح.'],['الجاني','فاعل مرفوع بضمة مقدرة منع من ظهورها الثقل، وهو صاحب الحال.'],['تحرسُه الجنودُ','جملة فعلية في محل نصب حال، رابطها الضمير «الهاء».']]},{sentence:'لا تأكلوا الفاكهةَ وهي فجّةٌ.',meaning:'المعنى: لا تأكلوها وهي غير ناضجة.',parse:[['الفاكهةَ','مفعول به منصوب بالفتحة، وهو صاحب الحال.'],['وهي فجّةٌ','الواو واو الحال، و«هي» ضمير في محل رفع مبتدأ، و«فجّةٌ» خبر، والجملة في محل نصب حال، رابطها الواو والضمير.']]},{sentence:'طلع البدرُ بينَ السحابِ.',meaning:'المعنى: ظهر القمر وهو وسط السحاب.',parse:[['البدرُ','فاعل مرفوع بالضمة، وهو صاحب الحال.'],['بينَ','ظرف مكان منصوب بالفتحة، وهو حال، وهو مضاف.'],['السحابِ','مضاف إليه مجرور بالكسرة.']]}],
guidedPractice:{prompt:'عيّن نوع الحال ورابطها في: غاب أخوك وقد حضر جميع الأصدقاء.',hint:'هل في جملة الحال ضمير يعود على «أخوك»؟',answer:'جملة فعلية رابطها الواو فقط.',explanation:'القاعدة 147.'},
summary:['تجيء الحال مفردًا أو جملة اسمية أو جملة فعلية أو ظرفًا أو جارًّا ومجرورًا.','جملة الحال لا بد لها من رابط.','الرابط الواو وحدها أو الضمير وحده أو هما معًا.'],
commonMistakes:['عدّ جملة الحال خبرًا.','نسيان الرابط عند الإعراب.','عدّ الظرف أو الجار والمجرور في الحال جملة.'],
bookExamples:['رجع القائدُ منصورًا.','ركبنا البحرَ هائجًا.','لا تأكلوا الطعامَ حارًّا.','حضر الضيوفُ والمضيفُ غائبٌ.','اصطفّتِ الجنودُ سيوفُهم مشهورةٌ.','لا تأكلوا الفاكهةَ وهي فجّةٌ.','غاب أخوك وقد حضر جميعُ الأصدقاء.','ذهب الجاني تحرسُه الجنودُ.','قطف الأولادُ الأزهارَ ولمّا تتفتّحْ.','راقني الوردُ وسطَ البستانِ.','أبصرتُ الخطيبَ فوقَ المنبرِ.','طلع البدرُ بينَ السحابِ.','تألّم الطائرُ في القفصِ.','اشتريتُ السلّةَ من التين بثمنٍ قليلٍ.','بعتُ الثمرَ على شجرِه.'],
inquiry:['انظر إلى الأمثلة: كل منها يشتمل على حال تبيّن هيئة الفاعل أو المفعول به حين وقوع الفعل.','وإذا تأملت الحال وجدتها في الطائفة الأولى مفردة، وفي الثانية جملة اسمية، وفي الثالثة جملة فعلية، وفي الرابعة ظرفًا، وفي الخامسة جارًّا ومجرورًا.','وانظر إلى الجمل الواقعة أحوالًا في الطائفتين الثانية والثالثة: كل جملة تشتمل على رابط يربطها بصاحب الحال، وهو إما الواو وحدها وتسمى واو الحال، وإما الضمير وحده، وإما هما معًا. ولن تجد جملة حال بغير رابط.'],
exercises:[{title:'تمرين 2',tasks:[{ask:'عيّن في الجمل الآتية ما جاء من الأحوال مفردًا، أو جملة اسمية، أو جملة فعلية، أو ظرفًا، أو جارًّا ومجرورًا',items:['دخل اللص المنزل وأهله نائمون، فسرق ما فيه من الأمتعة الثمينة، ثم خرج ولم يشعر به أحد.','ذهب العمال إلى أعمالهم مملوئين نشاطًا، ثم عادوا منها وقد بدت عليهم آثار التعب والإجهاد.','اشترى التاجر العنب على كرمه، ثم قطفه ناضجًا، وباعه رابحًا فيه.','أبصرتُ الطائر فوق الغصن، وسمعته يغرد تغريدًا حسنًا.','نظرتُ السمك تحت الماء، فألقيتُ شبكتي قاصدًا صيده، فخرجت الشبكة لا تحمل شيئًا، فألقيتها مرة ثانية، فخرجت وفيها اثنتا عشرة سمكة صغيرة.','باع الفلاح قطنه في غير تؤدة، وعاد من السوق نادمًا.','من جلس وهو صغير حيث يحب، جلس وهو كبير حيث يكره.']}]},{title:'تمرين 3',tasks:[{ask:'عيّن الرابط الذي يربط جملة الحال بصاحبها في كل جملة من الجمل الآتية',items:['أكل فريد وهو شبعان ثم قام يشكو ألمًا في معدته.','قرأت الكتاب وما وجدت فيه كلمة غريبة.','أجلّ أستاذي غاب أو حضر.','نمت الأشجار ولما تثمر.','استيقظنا من النوم وما طلعت الشمس.','ركبت السفينة والبحر هائج.','مكث الضيوف عندنا يومين ما قصّرنا في إكرامهم.','لا تنم ونوافذ الغرفة مقفلة.','قابلت أخاك وقد عاد من سفره.']}]},{title:'تمرين 4',tasks:[{ask:'أكمل كل جملة من الجمل الآتية بوضع حال مفردة مرة، وغير مفردة أخرى',items:['لا تمش في الليل ...','عاد الجنود ...','فر المجرمون من السجن ...','يعود الأطفال من اللعب ...','ذهبت الماشية إلى المرعى ...','لا تأكل الطعام ...','أقبلت الخيل ...','حضر الجاني أمام القاضي ...','لم تؤذون أخاكم ...','البس ثيابك ...']}]},{title:'تمرين 5',tasks:[{ask:'كوّن جملًا تجيء فيها الألفاظ التالية أحوالًا',items:['مستبشرًا','ظافرًا','آسفين','وأنت غضبان','وقد أعياهم التعب','مع إخوته','مسرعين','جاهلات','والحراس نيام']}]},{title:'تمرين 6',tasks:[{ask:'اجعل الحال المفردة في كل مثال من الأمثلة الآتية حالًا غير مفردة',items:['جلس المذنب خائفًا.','باع الفلاح قطنه رخيصًا.','يعجبني الغني متواضعًا.','عاد التاجر رابحًا.','أحب التلميذ مجتهدًا.','لا تختلط بالناس مريضًا.','سمعت المريض شاكيًا.','اصفح عمن أتاك معتذرًا.','أبصرت الورد مفتّحًا.','انظر إلى السماء ممطرة.']}]},{title:'تمرين 7',tasks:[{ask:'اجعل جملة الحال في كل مثال من الأمثلة الآتية حالًا مفردة',items:['تمر بنا الأيام ونحن لاهون.','جاء المذنب يعتذر عن ذنبه.','رجع السابق يتصبب عرقًا.','ركبت الحصان وهو متعب.','فارقت إخواني وأنا منقبض الصدر.','سمعت الخطيب يأسر القلوب بحسن لفظه.','أبصرت ثمر البستان يتساقط من شجره.','غرقت السفينة وقد كان منظرها رهيبًا.']}]},{title:'تمرين 9',tasks:[{ask:'كوّن ثلاث جمل تجيء الحال في كل منها جملة اسمية ورابطها الواو فقط',items:[]},{ask:'كوّن ثلاث جمل تجيء الحال في كل منها جملة فعلية ورابطها الواو فقط',items:[]},{ask:'كوّن ثلاث جمل تجيء الحال في كل منها جملة اسمية ورابطها الضمير فقط',items:[]},{ask:'كوّن ثلاث جمل تجيء الحال في كل منها جملة فعلية ورابطها الضمير فقط',items:[]},{ask:'كوّن ثلاث جمل تجيء الحال في كل منها جملة اسمية ورابطها الواو والضمير معًا',items:[]},{ask:'كوّن ثلاث جمل تجيء الحال في كل منها جملة فعلية ورابطها الواو والضمير معًا',items:[]}]},{title:'تمرين 12 في الإعراب',tasks:[{ask:'أعرب الجمل الآتية على نموذج الكتاب',items:['خرج الأولاد وهم فرحون.','أبصرت عليًّا مع أصدقائه.','لعب الأطفال في نشاط وعادوا مسرورين.'],model:'نموذج: ركبتُ السفينةَ والنسيمُ عليلٌ. ← ركبتُ: فعل ماضٍ مبني على السكون، والتاء ضمير في محل رفع فاعل. السفينةَ: مفعول به منصوب. والنسيمُ: الواو واو الحال حرف مبني على الفتح، والنسيمُ مبتدأ مرفوع بالضمة. عليلٌ: خبر المبتدأ مرفوع بالضمة. وجملة المبتدأ والخبر حال في محل نصب.'}]}],exercisesFromBook:true};

IC.lessonDetails['tamyiz']={sentenceExplanation:'«رطلًا» اسم مبهم من أسماء الوزن، و«بلحًا» تمييز يبيّن المراد منه.',fullParse:[['اشتريتُ','فعل ماضٍ مبني على السكون لاتصاله بتاء الفاعل، والتاء ضمير في محل رفع فاعل.'],['رطلًا','مفعول به منصوب بالفتحة، وهو مميَّز.'],['بلحًا','تمييز منصوب بالفتحة الظاهرة.']],lessonTemplateVersion:1,reviewStatus:R,
learningSteps:[{title:'ابحث عن الإبهام',text:'أي اسم يصلح لأشياء كثيرة؟'},{title:'عيّن المميَّز',text:'ملفوظ (وزن أو كيل أو مساحة أو عدد) أم ملحوظ؟'},{title:'عيّن التمييز',text:'الاسم الذي أزال الإبهام.'}],
workedExamples:[{sentence:'في الحقلِ عشرون بقرةً.',meaning:'المعنى: عدد البقر في الحقل عشرون.',parse:[['عشرون','مبتدأ مؤخر مرفوع بالواو لأنه ملحق بجمع المذكر السالم، وهو مميَّز من أسماء العدد.'],['بقرةً','تمييز منصوب بالفتحة الظاهرة.']]},{sentence:'فاضَ القلبُ سرورًا.',meaning:'المعنى: امتلأ القلب سرورًا.',parse:[['فاضَ','فعل ماضٍ مبني على الفتح.'],['القلبُ','فاعل مرفوع بالضمة.'],['سرورًا','تمييز منصوب بالفتحة، ومميَّزه ملحوظ مفهوم من الجملة.']]},{sentence:'باعني التاجرُ ذراعًا حريرًا.',meaning:'المعنى: باعني حريرًا مقداره ذراع.',parse:[['باعني','فعل ماضٍ مبني على الفتح، والنون للوقاية، والياء ضمير في محل نصب مفعول به أول.'],['التاجرُ','فاعل مرفوع بالضمة.'],['ذراعًا','مفعول به ثانٍ منصوب بالفتحة، وهو مميَّز من أسماء المساحة.'],['حريرًا','تمييز منصوب بالفتحة.']]}],
guidedPractice:{prompt:'عيّن التمييز والمميَّز في: الفيلُ أكبرُ من الجملِ جسمًا.',hint:'ما الذي أُبهم في «أكبر»؟',answer:'التمييز «جسمًا»، والمميَّز ملحوظ مفهوم من الجملة (أكبر في أي شيء؟).',explanation:'القاعدة 149.'},
summary:['التمييز اسم يزيل الإبهام عن اسم قبله.','المميَّز ملفوظ إن كان من أسماء الوزن والكيل والمساحة والعدد.','المميَّز ملحوظ إن فُهم من الجملة ولم يُذكر.'],
commonMistakes:['عدّ التمييز حالًا لأنه منصوب.','الخلط بين المميَّز والتمييز.','البحث عن المميَّز الملحوظ في الجملة وهو غير مذكور.'],
bookExamples:['اشتريتُ رطلًا بلحًا.','غلّتِ الأرضُ إردبًّا قمحًا.','باعني التاجرُ ذراعًا حريرًا.','في الحقلِ عشرون بقرةً.','طابَ المكانُ هواءً.','فاضَ القلبُ سرورًا.','العنبُ من ألذّ أنواعِ الفاكهةِ طعمًا.','القاهرةُ أكثرُ من الإسكندريةِ سكّانًا.'],
inquiry:['إذا قلت: «اشتريتُ رطلًا» لم يفهم السامع ما تريده بالرطل؛ لأنه اسم مبهم يصلح لمعانٍ كثيرة. فإذا قلت «بلحًا» زال الإبهام؛ لأنك ميّزت له الرطل. ولذلك يسمى «بلحًا» تمييزًا، ويسمى «رطلًا» مميَّزًا.','والمميَّز في الأمثلة الأربعة الأولى مذكور في اللفظ: رطل (وزن)، وإردب (كيل)، وذراع (مساحة)، وعشرون (عدد).','وفي الأمثلة الأربعة الأخيرة لا نجد للمميَّز ذكرًا، ولكن السامع يلحظه؛ فإذا سمع «طاب المكان» لحظ أن الذي طاب شيء منسوب للمكان، ولا يدري أهو ماؤه أم تربته أم هواؤه. فإذا ذُكر التمييز تعيّن المراد.'],
exercises:[{title:'تمرين 2',tasks:[{ask:'عيّن في الجمل الآتية تمييز الوزن، وتمييز المساحة، وتمييز الكيل',items:['يقتتل الفلاحون على شبر أرض يغتصبه أحدهم من الآخر.','اشتريت ذراعين كتانًا ورطلين بنًّا.','قيراط ماسًا خير من قيراطين ياقوتًا.','أطعمت الحصان قدحين شعيرًا وسفينة دلوًا ماءً.','ما في الأرض قدر راحة ظلًّا.','يخرج الفدان نحو خمسة قناطير من القطن، ونحو سبعة أرادب من القمح.']}]},{title:'تمرين 3',tasks:[{ask:'أكمل الجمل الآتية بوضع ألفاظ التمييز المناسبة في الأماكن الخالية',items:['الفضة أرفع ... من النحاس.','الكمثرى ألذ من التفاح ...','الأنبياء أصدق الناس ...','يبتهج الشجاع إذا انتصر على عدو يماثله ...','دخلت حديقة الحيوان، فوجدت الزرافة أطولها ... والطاووس أجملها ... والفيل أضخمها ... والأسد أشدها ... والقرد أكثرها ...','الشمس أكبر ... من القمر وأسطع منه ...']}]},{title:'تمرين 5',tasks:[{ask:'اجعل كل اسم من الأسماء الآتية تمييزًا في جملة مناسبة',items:['سكرًا','قصبًا','بأسًا','طولًا','أخلاقًا','رطلًا','هواءً','عقلًا','طعمًا','ثمنًا']}]}],exercisesFromBook:true};

IC.lessonDetails['tamyiz-ruling']={sentenceExplanation:'العدد «ثلاث» من الثلاثة إلى العشرة، فيجب جرّ تمييزه جمعًا: ثلاثَ شجراتٍ.',fullParse:[['غرستُ','فعل ماضٍ مبني على السكون لاتصاله بتاء الفاعل، والتاء ضمير في محل رفع فاعل.'],['ثلاثَ','مفعول به منصوب بالفتحة، وهو مضاف.'],['شجراتٍ','مضاف إليه (تمييز) مجرور بالكسرة؛ جمع مؤنث سالم.']],lessonTemplateVersion:1,reviewStatus:R,
learningSteps:[{title:'حدّد المميَّز',text:'وزن/كيل/مساحة، أم عدد، أم ملحوظ؟'},{title:'إن كان عددًا',text:'ثلاثة إلى عشرة، أم أحد عشر إلى تسعة وتسعين، أم مائة وألف؟'},{title:'احكم',text:'القاعدة 150 أو 151 أو 152.'}],
workedExamples:[{sentence:'رأيتُ أحدَ عشرَ فارسًا.',meaning:'المعنى: رأيتُ فرسانًا عددهم أحد عشر.',parse:[['أحدَ عشرَ','عدد مركب مبني على فتح الجزأين في محل نصب مفعول به.'],['فارسًا','تمييز مفرد منصوب بالفتحة.']]},{sentence:'في الحديقةِ ألفُ شجرةٍ.',meaning:'المعنى: عدد الأشجار ألف.',parse:[['ألفُ','مبتدأ مؤخر مرفوع بالضمة، وهو مضاف.'],['شجرةٍ','مضاف إليه (تمييز) مفرد مجرور بالكسرة.']]},{sentence:'حسُن الغلامُ كلامًا.',meaning:'المعنى: حسُن الغلام في كلامه.',parse:[['حسُن','فعل ماضٍ مبني على الفتح.'],['الغلامُ','فاعل مرفوع بالضمة.'],['كلامًا','تمييز منصوب بالفتحة، ومميَّزه ملحوظ.']]}],
guidedPractice:{prompt:'ما وجوه التمييز في: شربتُ رطلًا لبنًا؟',hint:'هو من أسماء الوزن.',answer:'النصب «رطلًا لبنًا»، والجر بالإضافة «رطلَ لبنٍ»، والجر بمن «رطلًا من لبنٍ».',explanation:'القاعدة 150.'},
summary:['تمييز الوزن والكيل والمساحة ينصب أو يجر بالإضافة أو بمن.','تمييز العدد: جمع مجرور (3–10)، ومفرد منصوب (11–99)، ومفرد مجرور (مائة وألف).','التمييز الذي مميَّزه ملحوظ منصوب دائمًا.'],
commonMistakes:['نصب تمييز الثلاثة إلى العشرة.','جر تمييز أحد عشر إلى تسعة وتسعين.','جر التمييز الملحوظ.'],
bookExamples:['شربتُ رطلًا لبنًا (أو رطلَ لبنٍ، أو رطلًا من لبنٍ).','أوقدتُ قنطارًا فحمًا (أو قنطارَ فحمٍ).','عندي مثقالُ ذهبٍ.','شربتُ كوبًا ماءً (أو كوبَ ماءٍ).','زرعتُ فدّانًا أرزًا (أو فدّانَ أرزٍ).','غرستُ ثلاثَ شجراتٍ.','أكلتُ أربعَ تفاحاتٍ.','اشتريتُ خمسةَ أقلامٍ.','في الأسبوعِ سبعةُ أيامٍ.','رأيتُ أحدَ عشرَ فارسًا.','في الشهرِ ثلاثون يومًا.','في القنطارِ مائةُ رطلٍ.','في الحديقةِ ألفُ شجرةٍ.','حسُن الغلامُ كلامًا.','اعتدل الرجلُ قامةً.','الفيلُ أكبرُ من الجملِ جسمًا.'],
inquiry:['تأمل المميَّز في الأمثلة الأولى: من أسماء الوزن في الثلاثة الأولى، ومن أسماء الكيل في الثانية، ومن أسماء المساحة في الثالثة. والتمييز في كل منها يأتي على صور ثلاث: منصوبًا، أو مجرورًا بالإضافة، أو مجرورًا بمن.','وأسماء العدد في الأقسام الثلاثة: من ثلاثة إلى عشرة، ومن أحد عشر إلى تسعة وتسعين، ومائة وألف. وتمييزها في الأول جمع مجرور، وفي الثاني مفرد منصوب، وفي الثالث مفرد مجرور.','وإذا كان المميَّز ملحوظًا فالتمييز منصوب دائمًا.'],
exercises:[{title:'تمرين 1',tasks:[{ask:'عيّن في الجمل الآتية ألفاظ التمييز التي تجيء بعد مميَّز ملفوظ والتي تجيء بعد مميَّز ملحوظ',items:['للحجرة ثلاث شبابيك، وفي كل شباك أربعة أعواد من الحديد.','جاء الرسول يقبض وجهه بشرًا.','أطعمت الدجاجة ملء الكف حبًّا.','باع التاجر خمسة عشر قنطارًا قطنًا، وعشرين إردبًّا شعيرًا.','البرتقال من ألذ أنواع الفاكهة طعمًا، وأطولها بقاءً، وأكثرها فائدة.','في الكتاب خمس وتسعون صفحة، وفي كل صفحة تسعة عشر سطرًا.','الريف أنقى من المدن هواءً، وأجمل منظرًا.','الذهب أقل صلابة من الحديد.']}]},{title:'تمرين 4',tasks:[{ask:'ميّز الأعداد المذكورة في الجمل الآتية بمعدودات تناسبها',items:['في السنة اثنا عشر ... وفي الشهر ثلاثون ... وفي اليوم أربع وعشرون ...','طول الطريق ألف ... وعرضه عشرون ...','في المدرسة خمسة وستون ومائتا ... وتسعة عشر ...','يقطع القطار في الساعة خمسين ...','عمر أخيك الآن إحدى وعشرون ... وثلاثة ... وأحد عشر ...','غزا المدينة جيش يتألف من ألفين وأربعمائة ...','قرأت من الكتاب مائة وعشرين ... وبقي منه أربع عشرة ...','يشتمل المنزل على بهوين وتسع ...']}]},{title:'تمرين 6',tasks:[{ask:'غيّر التمييز في الجمل الآتية من صورته التي جاء عليها إلى كل صورة أخرى ممكنة له، وراعِ ما يستدعيه ذلك من التغيير في المميَّز',items:['رأيت البنت وهي تحمل جرة ماء.','مثقال ذهبًا خير من رطل نحاسًا.','اشتريت مائتي ذراع أرضًا.','اشتريت قفصين عنبًا.','باع التاجر قنطارًا صابونًا.','زكاة الفطر نصف صاع برًّا.']}]},{title:'تمرين 7',tasks:[{ask:'كوّن ثلاث جمل يكون التمييز في كل منها منصوبًا والمميَّز اسمًا من أسماء الكيل',items:[]},{ask:'كوّن ثلاث جمل يكون التمييز في كل منها مجرورًا والمميَّز اسمًا من أسماء الوزن',items:[]},{ask:'كوّن ثلاث جمل يكون التمييز في كل منها منصوبًا والمميَّز اسمًا من أسماء المساحة',items:[]}]},{title:'تمرين 8',tasks:[{ask:'كوّن ثلاث جمل يكون التمييز فيها جمعًا مجرورًا والمميَّز اسمًا من أسماء العدد',items:[]},{ask:'كوّن ثلاث جمل يكون التمييز فيها مفردًا منصوبًا والمميَّز اسمًا من أسماء العدد',items:[]},{ask:'كوّن ثلاث جمل يكون التمييز فيها مفردًا مجرورًا والمميَّز اسمًا من أسماء العدد',items:[]},{ask:'كوّن ثلاث جمل يكون المميَّز فيها ملحوظًا',items:[]}]},{title:'تمرين 10 في الإعراب',tasks:[{ask:'أعرب الأمثلة الآتية على نموذج الكتاب',items:['أكلتِ الخيلُ إردبًّا شعيرًا.','باضتِ الدجاجة ثلاث بيضات.','في الميدان عشرون جوادًا.','العالم العامل أرفع من ذوي المال قدرًا.'],model:'نموذج: باع التاجرُ درهمين مسكًا. ← باع: فعل ماضٍ مبني على الفتح. التاجرُ: فاعل مرفوع بالضمة الظاهرة. درهمين: مفعول به منصوب بالياء لأنه مثنى. مسكًا: تمييز منصوب بالفتحة الظاهرة.'}]}],exercisesFromBook:true};

