function inferQuestionType(prompt){if(/لماذا|سبب|عل\s*؟|لِمَ/.test(prompt))return 'تعليل نحوي';if(/علامة/.test(prompt))return 'تعليل العلامة';if(/ما إعراب|إعراب/.test(prompt))return 'إعراب كلمة';if(/ما نوع|نوع كلمة/.test(prompt))return 'تصنيف نوع الكلمة';if(/أي الجمل|أي جملة/.test(prompt))return 'تمييز تركيب';if(/المبتدأ|الخبر|الفاعل|المفعول به|المضاف إليه|النعت|حرف الجر/.test(prompt))return 'تحديد الوظيفة النحوية';return 'فهم القاعدة';}
window.IraabContent.questions.forEach(q=>{
  q.source=q.source||'إعداد تعليمي داخلي — يحتاج مراجعة مدرس متخصص';
  q.reviewStatus=q.reviewStatus||'قيد المراجعة المتخصصة';
  q.gradeScope=q.gradeScope||'مسار تأسيسي عام غير مربوط بصف دراسي رسمي';
  q.correctIndex=Number.isInteger(q.correctIndex)?q.correctIndex:q.options.findIndex(o=>o.correct);
  q.questionType=q.questionType||inferQuestionType(q.prompt);
  q.prerequisites=q.prerequisites||lessonPrerequisites[q.lessonId]||[];
  q.misconception=q.misconception||questionSkills[q.lessonId]||'يحتاج التشخيص التفصيلي إلى تحليل إجابة الطالب';
  q.optionFeedback=q.optionFeedback||q.options.map(o=>o.correct?'':`راجع ${questionSkills[q.lessonId]||q.skill}، ثم قارن وظيفة الكلمة بما يطلبه السؤال.`);
});

